INSERT INTO `craft_entryversions` VALUES (3,7,3,1,'en_us',1,'','{\"typeId\":\"3\",\"authorId\":\"1\",\"title\":\"The Black Panther Party: Oakland and Chicago\",\"slug\":\"the-black-panther-party-oakland-and-chicago\",\"postDate\":1408505369,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"13\":[\"6\"],\"5\":{\"date\":\"3\\/7\\/2013\"},\"6\":\"\"}}','2014-08-20 03:29:29','2014-08-20 03:29:29','4a81f88e-d8c5-42dd-9916-d0845cc8298c'),(4,7,3,1,'en_us',2,'','{\"typeId\":\"3\",\"authorId\":\"1\",\"title\":\"The Black Panther Party: Oakland and Chicago\",\"slug\":\"2013-03-07\",\"postDate\":1408505340,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"13\":[\"6\"],\"5\":{\"date\":\"3\\/7\\/2013\"},\"6\":\"\"}}','2014-08-20 03:46:21','2014-08-20 03:46:21','f3f96711-3901-476a-8dfd-40593271f724'),(5,8,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Donna Murch\",\"slug\":\"donna-murch\",\"postDate\":1408506565,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Rutgers University New Brunswick\",\"10\":\"<p>Dr. Murch\\u2019s is an associate professor of History at Rutgers&nbsp;University in the School of Arts and Sciences. Her interests include&nbsp;the urban history of California and New York; Civil Rights, Black&nbsp;Power and postwar social movements; history of policing and&nbsp;prisons; and the political economy of drugs. Currently, she is&nbsp;researching the postwar history of the Bronx and completing a new&nbsp;book on youth culture and underground economy. She is also the&nbsp;author of <em>Living for the City: Migration, Education, and the Rise of&nbsp;<\\/em><em>the Black Panther Party in Oakland, California<\\/em>, University of North&nbsp;Carolina Press, October 2010.<\\/p>\",\"9\":\"dmurch@history.rutgers.edu\",\"11\":\"http:\\/\\/history.rutgers.edu\\/faculty-directory\\/249-murch-donna\",\"12\":\"\",\"8\":\"\"}}','2014-08-20 03:49:26','2014-08-20 03:49:26','2a782104-3127-4bb5-84b2-9d69d8ebfee8'),(6,7,3,1,'en_us',3,'','{\"typeId\":\"3\",\"authorId\":\"1\",\"title\":\"The Black Panther Party: Oakland and Chicago\",\"slug\":\"2013-03-07\",\"postDate\":1408505340,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"13\":[\"6\"],\"5\":{\"date\":\"3\\/7\\/2013\"},\"6\":\"\",\"14\":[\"8\"]}}','2014-08-20 03:50:16','2014-08-20 03:50:16','44462ebf-e653-405b-9c66-09a0c98fde32'),(8,11,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Jakobi Williams\",\"slug\":\"jakobi-williams\",\"postDate\":1408550588,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Indiana University\",\"10\":\"<p>Dr. Williams was born and raised on the south side of Chicago. He received his B.A&gt; in History and minor in Black American Studies from Southern Illinois University, Carbondale (2000). He earned both his M.A. in African American Studies from UCLA (2002) and Ph.D. in History from UCLA (2008). His research interests centered on questions of resistance and the social justice revolutions found within the historic African American community. His most recent book is, From the Bullet to the Ballot: The Illinois Chapter of the Black Panther Party and Racial Coalition Politics in Chicago.<\\/p>\",\"9\":\"jakowill@indiana.edu\",\"11\":\"http:\\/\\/www.indiana.edu\\/~histweb\\/faculty\\/Display.php?Faculty_ID=172\",\"12\":\"\",\"8\":\"jakobiwill\"}}','2014-08-20 16:03:09','2014-08-20 16:03:09','9418f552-ed31-4916-abb2-14654a5ed461'),(9,12,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Robyn Spencer\",\"slug\":\"robyn-spencer\",\"postDate\":1408550720,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Lehman College CUNY\",\"10\":\"<p>Dr. Spencer is a professor of African American History at Lehman&nbsp;College. She also taught African and African American Studies andHistory at Penn State University from 2001-2007. Before that, she&nbsp;was a Visiting Predoctoral Fellow at Randolph College in&nbsp;Lynchburg, Virginia. Her areas of interest include black social&nbsp;protest after World War II, urban and working-class radicalism, and&nbsp;gender. She is the author of<em> Mad at History<\\/em>, and is currently&nbsp;completing a book about the Black Panther Party.<\\/p>\",\"9\":\"\",\"11\":\"http:\\/\\/www.lehman.edu\\/academics\\/arts-humanities\\/history\\/historyspencer.php\",\"12\":\"\",\"8\":\"ProfRobyn\"}}','2014-08-20 16:05:20','2014-08-20 16:05:20','8c9cdf46-fc4a-4c7b-8363-f028ba3e39f8'),(10,7,3,1,'en_us',4,'','{\"typeId\":\"3\",\"authorId\":\"1\",\"title\":\"The Black Panther Party: Oakland and Chicago\",\"slug\":\"2013-03-07\",\"postDate\":1408505340,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"13\":[\"6\",\"10\"],\"5\":{\"date\":\"3\\/7\\/2013\"},\"6\":\"\",\"14\":[\"8\",\"11\",\"12\"]}}','2014-08-20 16:06:11','2014-08-20 16:06:11','d37f11af-8c9c-41df-a9d3-37834fa2f0f4'),(11,21,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"David Goldberg\",\"slug\":\"david-goldberg\",\"postDate\":1408555942,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Wayne State University\",\"10\":\"<p>David Goldberg\\u2019s book <em>Black Power at Work: Community Control, Affirmative Action, and the Construction Industry<\\/em>, chronicles the history of direct action campaigns to open up the construction industry to black workers in the 1960s and 1970s. He is an assistant professor of Africana Studies at Wayne University and the director of Beyond the Urban Crisis: The Detroit Civil rights, Community Activism, and Labor History Project.<\\/p>\",\"9\":\"\",\"11\":\"\",\"12\":\"\",\"8\":\"\"}}','2014-08-20 17:32:22','2014-08-20 17:32:22','7018f632-5e86-45bf-9dc4-6e9f559bb123'),(12,22,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Laura Hill\",\"slug\":\"laura-hill\",\"postDate\":1408556380,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Bloomfield College\",\"10\":\"<p>Dr. Hill is an assistant professor of History at Bloomfield College.&nbsp;She is the author of \\\"We Are Black Folk First: the Black Freedom&nbsp;Struggle in Rochester, NY\\u201d and \\u201cThe Making of Malcolm X\\\" published in <em>The Sixties: A Journal of History Politics and Culture<\\/em> in&nbsp;\\ufffcJanuary 2011. She is also an editor of&nbsp;The Business of Black Power:&nbsp;\\ufffcCommunity Development, Capitalism and Corporate&nbsp;Responsibility&nbsp;in Postwar America. Dr. Hill currently has a manuscript in progress: <em>Strike the Hammer While the Iron is Hot: The Black Freedom&nbsp;<\\/em><em>Struggle in Rochester, NY 1940-1970<\\/em>.<\\/p>\",\"9\":\"Laura_Hill@bloomfield.edu\",\"11\":\"\",\"12\":\"\",\"8\":\"\"}}','2014-08-20 17:39:40','2014-08-20 17:39:40','9024a70d-57e1-4758-8c91-a4ea0a35695b'),(13,23,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Jula Rabig\",\"slug\":\"jula-rabig\",\"postDate\":1408556706,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Julia Rabig\",\"10\":\"<p>Dr. Rabig received her PhD in 2007 from the University of Pennsylvania and has completed postdoctoral fellowships at the Center for the Study of African American Politics and the Frederick Douglass Institute for African and African American Studies. Her research analyzes civil rights and Black power activists\\u2019 attempts to remake local politics and federal policy in the aftermath of the 1960s urban uprisings. An adapted version of her doctoral dissertation \\u201cThe Fixers: Devolution, Development, and Civil Society in Newark, New Jersey, 1960-1990\\u2032\\u2032 appears in <em>Black Power at Work: Community Control and Affirmative Action in the Construction Industry, 1960s-70s<\\/em>.<\\/p>\",\"9\":\"julia.rabig@dartmouth.edu\",\"11\":\"http:\\/\\/www.dartmouth.edu\\/~wstudies\\/faculty\\/rabig.html\",\"12\":\"\",\"8\":\"\"}}','2014-08-20 17:45:07','2014-08-20 17:45:07','2b680cfc-9111-4ef1-84ce-5447d74dfc70'),(14,23,4,1,'en_us',2,'','{\"typeId\":\"5\",\"authorId\":\"1\",\"title\":\"Jula Rabig\",\"slug\":\"jula-rabig\",\"postDate\":1408556700,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Dartmouth College\",\"10\":\"<p>Dr. Rabig received her PhD in 2007 from the University of Pennsylvania and has completed postdoctoral fellowships at the Center for the Study of African American Politics and the Frederick Douglass Institute for African and African American Studies. Her research analyzes civil rights and Black power activists\\u2019 attempts to remake local politics and federal policy in the aftermath of the 1960s urban uprisings. An adapted version of her doctoral dissertation \\u201cThe Fixers: Devolution, Development, and Civil Society in Newark, New Jersey, 1960-1990\\u2032\\u2032 appears in <em>Black Power at Work: Community Control and Affirmative Action in the Construction Industry, 1960s-70s<\\/em>.<\\/p>\",\"9\":\"julia.rabig@dartmouth.edu\",\"11\":\"http:\\/\\/www.dartmouth.edu\\/~wstudies\\/faculty\\/rabig.html\",\"12\":\"\",\"8\":\"\"}}','2014-08-20 17:45:31','2014-08-20 17:45:31','7f29b54b-c88e-4b5c-9b15-9d17876182eb'),(15,23,4,1,'en_us',3,'','{\"typeId\":\"5\",\"authorId\":\"1\",\"title\":\"Jula Rabig\",\"slug\":\"jula-rabig\",\"postDate\":1408556700,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Dartmouth College\",\"10\":\"<p>Dr. Rabig received her PhD in 2007 from the University of Pennsylvania and has completed postdoctoral fellowships at the Center for the Study of African American Politics and the Frederick Douglass Institute for African and African American Studies. Her research analyzes civil rights and Black power activists\\u2019 attempts to remake local politics and federal policy in the aftermath of the 1960s urban uprisings. An adapted version of her doctoral dissertation \\u201cThe Fixers: Devolution, Development, and Civil Society in Newark, New Jersey, 1960-1990\\u2032\\u2032 appears in <em>Black Power at Work: Community Control and Affirmative Action in the Construction Industry, 1960s-70s<\\/em>.<\\/p>\",\"9\":\"julia.rabig@dartmouth.edu\",\"11\":\"http:\\/\\/www.dartmouth.edu\\/~wstudies\\/faculty\\/rabig.html\",\"12\":[\"24\"],\"8\":\"\"}}','2014-08-20 17:46:24','2014-08-20 17:46:24','094d9941-3172-450d-a014-6258ceb6472e'),(16,8,4,1,'en_us',2,'','{\"typeId\":\"5\",\"authorId\":\"1\",\"title\":\"Donna Murch\",\"slug\":\"donna-murch\",\"postDate\":1408506540,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Rutgers University New Brunswick\",\"10\":\"<p>Dr. Murch\\u2019s is an associate professor of History at Rutgers&nbsp;University in the School of Arts and Sciences. Her interests include&nbsp;the urban history of California and New York; Civil Rights, Black&nbsp;Power and postwar social movements; history of policing and&nbsp;prisons; and the political economy of drugs. Currently, she is&nbsp;researching the postwar history of the Bronx and completing a new&nbsp;book on youth culture and underground economy. She is also the&nbsp;author of <em>Living for the City: Migration, Education, and the Rise of&nbsp;<\\/em><em>the Black Panther Party in Oakland, California<\\/em>, University of North&nbsp;Carolina Press, October 2010.<\\/p>\",\"9\":\"dmurch@history.rutgers.edu\",\"11\":\"http:\\/\\/history.rutgers.edu\\/faculty-directory\\/249-murch-donna\",\"12\":[\"25\"],\"8\":\"\"}}','2014-08-20 17:52:51','2014-08-20 17:52:51','e1122881-359d-4859-b344-364bd690910a'),(17,11,4,1,'en_us',2,'','{\"typeId\":\"5\",\"authorId\":\"1\",\"title\":\"Jakobi Williams\",\"slug\":\"jakobi-williams\",\"postDate\":1408550580,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Indiana University\",\"10\":\"<p>Dr. Williams was born and raised on the south side of Chicago. He received his B.A&gt; in History and minor in Black American Studies from Southern Illinois University, Carbondale (2000). He earned both his M.A. in African American Studies from UCLA (2002) and Ph.D. in History from UCLA (2008). His research interests centered on questions of resistance and the social justice revolutions found within the historic African American community. His most recent book is, From the Bullet to the Ballot: The Illinois Chapter of the Black Panther Party and Racial Coalition Politics in Chicago.<\\/p>\",\"9\":\"jakowill@indiana.edu\",\"11\":\"http:\\/\\/www.indiana.edu\\/~histweb\\/faculty\\/Display.php?Faculty_ID=172\",\"12\":[\"26\"],\"8\":\"jakobiwill\"}}','2014-08-20 17:53:02','2014-08-20 17:53:02','e13ef399-c8d7-420a-a928-d5e17e8fcfa5'),(18,12,4,1,'en_us',2,'','{\"typeId\":\"5\",\"authorId\":\"1\",\"title\":\"Robyn Spencer\",\"slug\":\"robyn-spencer\",\"postDate\":1408550700,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Lehman College CUNY\",\"10\":\"<p>Dr. Spencer is a professor of African American History at Lehman&nbsp;College. She also taught African and African American Studies andHistory at Penn State University from 2001-2007. Before that, she&nbsp;was a Visiting Predoctoral Fellow at Randolph College in&nbsp;Lynchburg, Virginia. Her areas of interest include black social&nbsp;protest after World War II, urban and working-class radicalism, and&nbsp;gender. She is the author of<em> Mad at History<\\/em>, and is currently&nbsp;completing a book about the Black Panther Party.<\\/p>\",\"9\":\"\",\"11\":\"http:\\/\\/www.lehman.edu\\/academics\\/arts-humanities\\/history\\/historyspencer.php\",\"12\":[\"27\"],\"8\":\"ProfRobyn\"}}','2014-08-20 17:53:11','2014-08-20 17:53:11','3bbcb7fc-5964-4e7c-810b-2f35d211ed54'),(19,28,3,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"The Economics of Black Power\",\"slug\":\"the-economics-of-black-power\",\"postDate\":1408557408,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"13\":[\"13\",\"17\"],\"5\":{\"date\":\"4\\/4\\/2013\"},\"6\":\"\",\"14\":[\"21\",\"22\",\"23\"]}}','2014-08-20 17:56:48','2014-08-20 17:56:48','f52e07f8-a220-4140-9e4b-2687122b352d'),(20,29,3,1,'en_us',1,'','{\"typeId\":\"6\",\"authorId\":\"1\",\"title\":\"Spring 2013\",\"slug\":\"spring-2013\",\"postDate\":1408557612,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"2\":\"\"}}','2014-08-20 18:00:12','2014-08-20 18:00:12','c1f3fe34-4079-4e65-ac7e-ba64c06248c9'),(21,31,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Brian Purnell\",\"slug\":\"brian-purnell\",\"postDate\":1408559206,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Bowdoin College\",\"10\":\"<p>Dr. Brian Purnell is Assistant Professor of Africana Studies and History at Bowdoin College. From 2004-2010, he taught at Fordham University and directed the Bronx African American History Project, a community-university partnership dedicated to finding and preserving the history of black people in the Bronx. He is the author of, Fighting Jim Crow in the County of Kings: The Congress of Racial Equality in Brooklyn, which won the Dixon Ryan Fox manuscript prize from the New York State Historical Association. In addition to his scholarship, Brian Purnell served as a scholarly advisor to \\u201cFighting for Justice: New York Voices of the Civil Rights Movement,\\u201d an oral history project led by the New York City Commission on Human Rights. Originally from Brooklyn, New York, he received his M.A. (2004) and Ph.D. (2006) in History at New York University and his B.A. (2000) in History and African American Studies from Fordham University.<\\/p>\",\"9\":\"bpurnell@bowdoin.edu \",\"11\":\"http:\\/\\/www.bowdoin.edu\\/faculty\\/b\\/bpurnell\\/\",\"12\":[\"30\"],\"8\":\"\"}}','2014-08-20 18:26:47','2014-08-20 18:26:47','3f63f9f2-cb01-49f5-a0cf-4cf09da3b432'),(22,32,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Clarence Taylor\",\"slug\":\"clarence-taylor\",\"postDate\":1408559270,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Baruch College CUNY\",\"10\":\"<p>Dr. Taylor was born and raised in Brooklyn, New York. He received his undergraduate degree from Brooklyn College, and his MA from New York University. Shortly after graduation from NYU, Taylor began teaching in the New York City public school system as a special education teacher. In 1984 Taylor left JHS 278 and became a social studies teacher at James Madison High School in Brooklyn. While teaching at James Madison, Clarence pursued his doctorate in history at Graduate School of the City University of New York. In 1991, Clarence received his PhD in American history and began teaching at Le Moyne College in Syracuse, New York. Prof. Taylor\\u2019s research interests are the modern civil rights and black power movements, African-American religion, and the modern history of New York City. He is the editor of <em>Civil Rights in New York City: From World War II to the Giuliani Era<\\/em> (Fordham University Press, 2011).<\\/p>\",\"9\":\"Clarence.Taylor@baruch.cuny.edu\",\"11\":\"http:\\/\\/www.baruch.cuny.edu\\/wsas\\/academics\\/history\\/ctaylor.htm\",\"12\":\"\",\"8\":\"\"}}','2014-08-20 18:27:50','2014-08-20 18:27:50','91bc09f7-5276-4710-9224-37bfe92d8ebd'),(23,33,3,1,'en_us',1,'','{\"typeId\":\"3\",\"authorId\":\"1\",\"title\":\"Freedom North: The Black Freedom Struggle in New York\",\"slug\":\"freedom-north\",\"postDate\":1408559640,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"13\":[\"18\",\"19\"],\"5\":{\"date\":\"05\\/02\\/2013\"},\"6\":\"\",\"14\":[\"31\",\"32\"]}}','2014-08-20 18:34:00','2014-08-20 18:34:00','fd344716-e604-406d-9442-c1c88704ae36'),(24,32,4,1,'en_us',2,'','{\"typeId\":\"5\",\"authorId\":\"1\",\"title\":\"Clarence Taylor\",\"slug\":\"clarence-taylor\",\"postDate\":1408559220,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Baruch College CUNY\",\"10\":\"<p>Dr. Taylor was born and raised in Brooklyn, New York. He received his undergraduate degree from Brooklyn College, and his MA from New York University. Shortly after graduation from NYU, Taylor began teaching in the New York City public school system as a special education teacher. In 1984 Taylor left JHS 278 and became a social studies teacher at James Madison High School in Brooklyn. While teaching at James Madison, Clarence pursued his doctorate in history at Graduate School of the City University of New York. In 1991, Clarence received his PhD in American history and began teaching at Le Moyne College in Syracuse, New York. Prof. Taylor\\u2019s research interests are the modern civil rights and black power movements, African-American religion, and the modern history of New York City. He is the editor of <em>Civil Rights in New York City: From World War II to the Giuliani Era<\\/em> (Fordham University Press, 2011).<\\/p>\",\"9\":\"Clarence.Taylor@baruch.cuny.edu\",\"11\":\"http:\\/\\/www.baruch.cuny.edu\\/wsas\\/academics\\/history\\/ctaylor.htm\",\"12\":[\"34\"],\"8\":\"\"}}','2014-08-20 18:36:03','2014-08-20 18:36:03','b570d142-22ca-41d5-b914-10f5f6653e85'),(25,23,4,1,'en_us',4,'','{\"typeId\":\"5\",\"authorId\":\"1\",\"title\":\"Julia Rabig\",\"slug\":\"jula-rabig\",\"postDate\":1408556700,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Dartmouth College\",\"10\":\"<p>Dr. Rabig received her PhD in 2007 from the University of Pennsylvania and has completed postdoctoral fellowships at the Center for the Study of African American Politics and the Frederick Douglass Institute for African and African American Studies. Her research analyzes civil rights and Black power activists\\u2019 attempts to remake local politics and federal policy in the aftermath of the 1960s urban uprisings. An adapted version of her doctoral dissertation \\u201cThe Fixers: Devolution, Development, and Civil Society in Newark, New Jersey, 1960-1990\\u2032\\u2032 appears in <em>Black Power at Work: Community Control and Affirmative Action in the Construction Industry, 1960s-70s<\\/em>.<\\/p>\",\"9\":\"julia.rabig@dartmouth.edu\",\"11\":\"http:\\/\\/www.dartmouth.edu\\/~wstudies\\/faculty\\/rabig.html\",\"12\":[\"24\"],\"8\":\"\"}}','2014-08-20 18:53:22','2014-08-20 18:53:22','1cb8f1a6-c54e-4595-97b2-8880f7c8a234'),(26,2,1,1,'en_us',1,'','{\"typeId\":\"1\",\"authorId\":null,\"title\":\"Homepage\",\"slug\":\"homepage\",\"postDate\":1408482960,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"2\":\"<p>The Schomburg Center for Research in Black Culture brings the campus to the community for a series of roundtable conversations on the first Thursday of each month. This inaugural series is curated by Professors Jeanne Theoharis (Brooklyn College\\/CUNY) and Komozi Woodard (Sarah Lawrence College), and introduces a new paradigm that challenges the older geography, leadership, ideology, culture and chronology of Civil Rights historiography. A special reading list has been compiled by series, and conversations will be videotaped and made available for public viewing at the Schomburg library. We encourage adult learners, educators and college students to join us each month for this dynamic learning experience!<\\/p>\",\"1\":\"Conversations in Black Freedom Studies\"}}','2014-08-21 20:26:24','2014-08-21 20:26:24','1790d7f9-1856-47f6-b6fd-38623f70dd95'),(27,2,1,1,'en_us',2,'','{\"typeId\":\"1\",\"authorId\":null,\"title\":\"Homepage\",\"slug\":\"homepage\",\"postDate\":1408482960,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"2\":\"The Schomburg Center for Research in Black Culture brings the campus to the community for a series of roundtable conversations on the first Thursday of each month. This inaugural series is curated by Professors Jeanne Theoharis (Brooklyn College\\/CUNY) and Komozi Woodard (Sarah Lawrence College), and introduces a new paradigm that challenges the older geography, leadership, ideology, culture and chronology of Civil Rights historiography. A special reading list has been compiled by series, and conversations will be videotaped and made available for public viewing at the Schomburg library. We encourage adult learners, educators and college students to join us each month for this dynamic learning experience!\",\"1\":\"Conversations in Black Freedom Studies\"}}','2014-08-21 20:43:06','2014-08-21 20:43:06','d2f6efd7-6fc3-4c46-a318-b245b1bc631a'),(28,37,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Michael West\",\"slug\":\"michael-west\",\"postDate\":1408655448,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Binghamton University SUNY\",\"10\":\"<p>Prof. West\\u2019s current research focuses on the interconnections and inter-relationships between the liberatory struggles of African peoples worldwide. His books include <em>The Rise of an African Middle Class: Colonial Zimbabwe, 1890-1965<\\/em> and <em>From Toussaint to Tupac: The Black International Since the Age of Revolution<\\/em> (edited with William Martin and Fanon Che Wilkins).<\\/p>\",\"9\":\"mwest@binghamton.edu\",\"11\":\"http:\\/\\/www.binghamton.edu\\/sociology\\/people\\/michael-west.html\",\"12\":[\"36\"],\"8\":\"\"}}','2014-08-21 21:10:48','2014-08-21 21:10:48','ba670a25-bd81-4b15-9301-386b2a47e382'),(29,38,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Akinyele Umoja\",\"slug\":\"akinyele-umoja\",\"postDate\":1408655597,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Georgia State University\",\"10\":\"<p>Prof. Umoja\\u2019s publications include \\u201cFrom Malcolm X to Omowale Malik Shabazz: The Transformation and Its Impact on the Black Liberation Struggle\\u201d in James Conyers and Andrew Smallwood, Malcolm X: Historical Reader and \\u201cAid to Children of Imprisoned Mothers: An Ethnographic Study,\\u201d \\u201cRepression Breeds Resistance: The Black Liberation Army and the Legacy of the Black Panther Party,\\u201d in Lance J. Jeffries, Black Power in the Belly of the Beast.<\\/p>\",\"9\":\"aadaku@gsu.edu\",\"11\":\"http:\\/\\/www2.gsu.edu\\/~wwwaad\\/11661.html\",\"12\":\"\",\"8\":\"\"}}','2014-08-21 21:13:18','2014-08-21 21:13:18','056885b8-bcf4-48d9-9f47-d9896a8e8b37'),(30,38,4,1,'en_us',2,'','{\"typeId\":\"5\",\"authorId\":\"1\",\"title\":\"Akinyele Umoja\",\"slug\":\"akinyele-umoja\",\"postDate\":1408655580,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Georgia State University\",\"10\":\"<p>Prof. Umoja\\u2019s publications include \\u201cFrom Malcolm X to Omowale Malik Shabazz: The Transformation and Its Impact on the Black Liberation Struggle\\u201d in James Conyers and Andrew Smallwood, Malcolm X: Historical Reader and \\u201cAid to Children of Imprisoned Mothers: An Ethnographic Study,\\u201d \\u201cRepression Breeds Resistance: The Black Liberation Army and the Legacy of the Black Panther Party,\\u201d in Lance J. Jeffries, Black Power in the Belly of the Beast.<\\/p>\",\"9\":\"aadaku@gsu.edu\",\"11\":\"http:\\/\\/www2.gsu.edu\\/~wwwaad\\/11661.html\",\"12\":[\"39\"],\"8\":\"\"}}','2014-08-21 21:13:42','2014-08-21 21:13:42','4a1d85a1-95b6-470a-8ad7-4e97dd3074c9'),(31,40,3,1,'en_us',1,'','{\"typeId\":\"3\",\"authorId\":\"1\",\"title\":\"Black Radical Internationalism\",\"slug\":\"black-radical-internationalism\",\"postDate\":1408655752,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"13\":[\"16\",\"5\",\"20\"],\"5\":{\"date\":\"06\\/06\\/2013\"},\"6\":\"\",\"14\":[\"37\",\"12\",\"38\"]}}','2014-08-21 21:15:53','2014-08-21 21:15:53','b6f3da4d-289d-4e68-bd82-a1a7fddc0696'),(32,41,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Jeanne Theoharis\",\"slug\":\"jeanne-theoharis\",\"postDate\":1408656028,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Brooklyn College CUNY\",\"10\":\"\",\"9\":\"jtheoharis@brooklyn.cuny.edu\",\"11\":\"http:\\/\\/www.brooklyn.cuny.edu\\/web\\/academics\\/faculty\\/faculty_profile.jsp?faculty=510\",\"12\":\"\",\"8\":\"JeanneTheoharis\"}}','2014-08-21 21:20:28','2014-08-21 21:20:28','ca3af406-a60f-4737-b594-27b64eebc53e'),(33,41,4,1,'en_us',2,'','{\"typeId\":\"5\",\"authorId\":\"1\",\"title\":\"Jeanne Theoharis\",\"slug\":\"jeanne-theoharis\",\"postDate\":1408656000,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Brooklyn College CUNY\",\"10\":\"<p>Jeanne Theoharis is Distinguished Professor of Political Science at Brooklyn College of the City University of New York.  Her most recent book is <em style=\\\"font-family: Arial, Helvetica, Verdana, Tahoma, sans-serif; font-size: 14px; background-color: initial;\\\">The Rebellious Life of Mrs. Rosa Parks<\\/em> which won a 2014 NAACP Image Award.  She and Komozi Woodard have edited three collections of new scholarship on the Black Freedom Struggle: <em style=\\\"font-family: Arial, Helvetica, Verdana, Tahoma, sans-serif; font-size: 14px; background-color: initial;\\\">Freedom North: Black Freedom Struggles Outside of the South, 1940-1980<\\/em>; <em style=\\\"font-family: Arial, Helvetica, Verdana, Tahoma, sans-serif; font-size: 14px; background-color: initial;\\\">Groundwork: Local Black Freedom Movements in America<\\/em> and <em style=\\\"font-family: Arial, Helvetica, Verdana, Tahoma, sans-serif; font-size: 14px; background-color: initial;\\\">Want to Start A Revolution?: Radical Women in the Black Freedom Struggle<\\/em> with Dayo Gore.<\\/p>\",\"9\":\"jtheoharis@brooklyn.cuny.edu\",\"11\":\"http:\\/\\/www.brooklyn.cuny.edu\\/web\\/academics\\/faculty\\/faculty_profile.jsp?faculty=510\",\"12\":[\"44\"],\"8\":\"JeanneTheoharis\"}}','2014-08-24 15:22:29','2014-08-24 15:22:29','0fbda674-91e2-4c93-ae92-9219d6466f93'),(34,45,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Komozi Woodard\",\"slug\":\"komozi-woodard\",\"postDate\":1408893838,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Sarah Lawrence College\",\"10\":\"<p>Komozi Woodard is Professor of History, Public Policy and Africana Studies at Sarah Lawrence College. Earning a Ph.D. in History at the University of Pennsylvania and B.A. in Sociology-Anthropology, Dr. Woodard held the Esther Raushenbush Professorship in History at Sarah Lawrence College; served on the Board of Directors of the Urban History Association; edited a few African American newspapers and cultural journals as well as Black Power & Black Arts Movement archives; directed an international news service and a radio news program; curated library, museum and college programs; and published hundreds of news and scholarly articles as well as six books, including these: <em style=\\\"font-family: Arial, Helvetica, Verdana, Tahoma, sans-serif; font-size: 14px; background-color: initial;\\\">A Nation within a Nation: Amiri Baraka (LeRoi Jones) and Black Power Politics<\\/em>; <em style=\\\"font-family: Arial, Helvetica, Verdana, Tahoma, sans-serif; font-size: 14px; background-color: initial;\\\">The Making of the New Ark; The Black Power Movement: Amiri Baraka from Black Arts to Black Radicalism<\\/em>, <em style=\\\"font-family: Arial, Helvetica, Verdana, Tahoma, sans-serif; font-size: 14px; background-color: initial;\\\">Freedom North,<\\/em> <em style=\\\"font-family: Arial, Helvetica, Verdana, Tahoma, sans-serif; font-size: 14px; background-color: initial;\\\">Groundwork<\\/em> and <em style=\\\"font-family: Arial, Helvetica, Verdana, Tahoma, sans-serif; font-size: 14px; background-color: initial;\\\">Want to Start a Revolution: Radical Women in the Black Freedom Struggle?<\\/em><\\/p><p>Komozi Woodard began as a civil rights & black power activist, then journalist as well as an economic adviser, urban planner and community developer. Woodard began teaching in 1968 when he established a Student Nonviolent Coordinating Committee or SNCC liberation school and when he initiated Africana Studies at Dickinson College. Woodard was a founding member of the Congress of African Students at Dickinson College, the international Congress of African People, the national Black Women\\u2019s United Front, the international African Liberation Support Committee, the National Black Political Assembly, the National Black United Front, the Anti-Imperialist Cultural Union and the Stop Killer Cop Campaign and so forth.<\\/p>\",\"9\":\"kwoodard@sarahlawrence.edu\",\"11\":\"http:\\/\\/www.slc.edu\\/faculty\\/woodard-komozi.html\",\"12\":[\"42\"],\"8\":\"\"}}','2014-08-24 15:23:58','2014-08-24 15:23:58','2fe186b6-dd8c-4768-aa1e-6613413983ad'),(35,47,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Barbara Ransby\",\"slug\":\"barbara-ransby\",\"postDate\":1408922878,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"University of Illinois, Chicago\",\"10\":\"<p>Barbara Ransby is Professor of History and African American Studies at the University of Illinois, Chicago.  She is the author of <em style=\\\"font-family: Arial, Helvetica, Verdana, Tahoma, sans-serif; font-size: 14px; background-color: initial;\\\">Ella Baker and the Black Radical Tradition&nbsp;<\\/em>and<em style=\\\"font-family: Arial, Helvetica, Verdana, Tahoma, sans-serif; font-size: 14px; background-color: initial;\\\"> Eslanda: The Large and Unconventional Life of Mrs. Paul Robeson<\\/em>.<\\/p>\",\"9\":\"bransby@uic.edu\",\"11\":\"http:\\/\\/www.uic.edu\\/depts\\/wsweb\\/people\\/faculty\\/ransby\\/ransby.html\",\"12\":[\"46\"],\"8\":\"BarbaraRansby\"}}','2014-08-24 23:27:58','2014-08-24 23:27:58','afd611eb-ef24-43e3-a011-ae65296056d6'),(36,50,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Mary Frances Berry\",\"slug\":\"mary-frances-berry\",\"postDate\":1408928040,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"University of Pennsylvania\",\"10\":\"<p>Mary Frances Berry is Geraldine R. Segal Professor of American Social Thought and Professor of History at the University of Pennsylvania and the author of <em>And Justice for All: The United States Commission on Civil Rights<\\/em><em>and the Continuing Struggle for Freedom in America<\\/em> and <em>Power in Words: The Stories behind Barack Obama\'s Speeches from the State House to the White House.<\\/em><\\/p>\",\"9\":\"mfberry@sas.upenn.edu\",\"11\":\"http:\\/\\/www.maryfrancesberry.com\\/\",\"12\":[\"49\"],\"8\":\"\"}}','2014-08-25 00:54:56','2014-08-25 00:54:56','4ddea5be-ad4c-4c18-9da5-d626951e7d02'),(37,53,3,1,'en_us',1,'','{\"typeId\":\"3\",\"authorId\":\"1\",\"title\":\"Honoring the Legacies of Rosa Parks and Eslanda Robeson\",\"slug\":\"parks-and-eslanda\",\"postDate\":1408928538,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"13\":[\"48\",\"51\",\"52\"],\"5\":{\"date\":\"7\\/20\\/2013\"},\"6\":\"\",\"14\":[\"47\",\"41\",\"50\"]}}','2014-08-25 01:02:18','2014-08-25 01:02:18','bef23702-cb08-4bc4-96df-7fe1796c4104'),(38,54,3,1,'en_us',1,'','{\"typeId\":\"6\",\"authorId\":\"1\",\"title\":\"Fall 2014\",\"slug\":\"fall-2014\",\"postDate\":1408930175,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"2\":\"\"}}','2014-08-25 01:29:35','2014-08-25 01:29:35','6b345425-6368-4be0-85a6-8819d76dbc41'),(39,55,3,1,'en_us',1,'','{\"typeId\":\"6\",\"authorId\":\"1\",\"title\":\"Fall 2013\",\"slug\":\"fall-2013\",\"postDate\":1408930338,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"2\":\"\"}}','2014-08-25 01:32:18','2014-08-25 01:32:18','27e42f07-e19f-40dd-80c5-4a0b56e5284e'),(40,59,3,1,'en_us',1,'','{\"typeId\":\"3\",\"authorId\":\"1\",\"title\":\"\\u200bThe Roots of Harlem Radicalism and Garveyism\",\"slug\":\"harlem-radicalism-and-garveyism\",\"postDate\":1408930500,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"2\":\"<p>Marcus Garvey\\u2019s Universal Negro Improvement Association (UNIA) spread its message of human rights around the modern world. His following in the American South grew when it fell in other regions. The social history and the census suggest that a Garvey household was a house full of women; and for many Black women Black business development was a measure against the threat of rape faced by Black domestic workers. For Black dock workers in cities like Newport News, owning a steam ship was a potent symbol of modernity. Thus, the Black Star Line was an important symbol for those workers. The UNIA spread its message of self-education through not only classes but also through the newspaper, the <em>Negro World<\\/em>, edited by the \\u201cSocrates of the Harlem Renaissance,\\u201d Hubert Harrison. Harrison also helped establish the Harlem street-corner education tradition. Another important journalist was John Edward Bruce, known by his pen name, Bruce Grit. Hubert Harrison, Marcus Garvey, Arturo Schomburg and John Edward Bruce were part of a large circle of grassroots intellectuals and educators who established those Harlem traditions of Black History and self- determination for Malcolm X and Black Liberation.<\\/p>\",\"13\":[\"56\",\"57\",\"58\"],\"5\":{\"date\":\"9\\/5\\/2013\"},\"6\":\"\",\"14\":\"\"}}','2014-08-25 01:38:26','2014-08-25 01:38:26','6d3c3df2-cb4a-4d89-b265-94d2b3c72520'),(41,61,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Mary Rolinson\",\"slug\":\"mary-rolinson\",\"postDate\":1408931949,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Georgia State University\",\"10\":\"<p>Dr. Rolinson is a professor for the history department at Georgia State University and is the author of <em>Grassroots Garveyism: The Universal Negro Improvement Association in the Rural South, 1920-1927<\\/em> (Chapel Hill: The University of North Carolina Press, 2007). Rolinson is currently working on two research projects: One is on Mabel Murphy Smythe, an African American woman who was an expert on economic development and politics in the post-World War II era. Rolinson\'s second project is tracing the remains of the Garvey Movement from 1940-1975 through an examination of the Thomas W. Harvey Papers.<\\/p>\",\"9\":\"mrolinson1@gsu.edu\",\"11\":\"http:\\/\\/www2.gsu.edu\\/~wwwhis\\/5557.html\",\"12\":[\"60\"],\"8\":\"\"}}','2014-08-25 01:59:09','2014-08-25 01:59:09','db2b893c-8230-4bae-af7a-aa054e8d0a66'),(42,63,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Jeffrey Perry\",\"slug\":\"jeffrey-perry\",\"postDate\":1408932226,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Independent\",\"10\":\"<p>Jeffrey B. Perry is an independent, working-class scholar formally educated at Princeton, Harvard, Rutgers, and Columbia. Dr. Perry was influenced toward serious study of matters of race and class in America through personal experiences and readings and through the work of an independent scholar and close personal friend, the late Theodore William Allen (1919-2005). He is the editor of <em>A Hubert Harrison Reader<\\/em> (Wesleyan University Press, 2001) and the forthcoming \\\"Writings of Hubert Harrison.\\\" He is also the author of <em>Hubert Harrison: The Voice of Harlem Radicalism, 1883-1918<\\/em> (Columbia University Press, 2008). He is currently working on Vol. 2 of the Hubert Harrison biography.&nbsp;<\\/p>\",\"9\":\"jeffreybperry@gmail.com\",\"11\":\"http:\\/\\/www.jeffreybperry.net\\/\",\"12\":[\"62\"],\"8\":\"\"}}','2014-08-25 02:03:46','2014-08-25 02:03:46','432a0b13-51b2-4469-99a7-b7a8ed78b133'),(43,65,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"William Seraile\",\"slug\":\"william-seraile\",\"postDate\":1408932455,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Lehman College CUNY (Emeritus)\",\"10\":\"<p>Professor Seraile retired from his post at Lehman in 2007, after thirty-six years of teaching. His most recent book is <em>Angels of Mercy: White Women and the History of New York\\u2019s Colored Orphan Asylum<\\/em>, which was published in 2006. He is the author of four books, including <em>Bruce Grit: The Black Nationalist Writings of John Edward Bruce<\\/em> (2003). He graduated from Central Washington University in 1963 with a B.A. in Social Science and holds an M.A. in the Teaching of History from Teacher\\u2019s College, Columbia University. He earned his Ph.D. in American history from the CUNY Graduate Center.<\\/p>\",\"9\":\"\",\"11\":\"\",\"12\":[\"64\"],\"8\":\"\"}}','2014-08-25 02:07:35','2014-08-25 02:07:35','e507c24d-d188-4b0d-9b9d-99939bd2f38b'),(44,59,3,1,'en_us',2,'','{\"typeId\":\"3\",\"authorId\":\"1\",\"title\":\"\\u200bThe Roots of Harlem Radicalism and Garveyism\",\"slug\":\"harlem-radicalism-and-garveyism\",\"postDate\":1408930500,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"2\":\"<p>Marcus Garvey\\u2019s Universal Negro Improvement Association (UNIA) spread its message of human rights around the modern world. His following in the American South grew when it fell in other regions. The social history and the census suggest that a Garvey household was a house full of women; and for many Black women Black business development was a measure against the threat of rape faced by Black domestic workers. For Black dock workers in cities like Newport News, owning a steam ship was a potent symbol of modernity. Thus, the Black Star Line was an important symbol for those workers. The UNIA spread its message of self-education through not only classes but also through the newspaper, the <em>Negro World<\\/em>, edited by the \\u201cSocrates of the Harlem Renaissance,\\u201d Hubert Harrison. Harrison also helped establish the Harlem street-corner education tradition. Another important journalist was John Edward Bruce, known by his pen name, Bruce Grit. Hubert Harrison, Marcus Garvey, Arturo Schomburg and John Edward Bruce were part of a large circle of grassroots intellectuals and educators who established those Harlem traditions of Black History and self- determination for Malcolm X and Black Liberation.<\\/p>\",\"13\":[\"56\",\"57\",\"58\"],\"5\":{\"date\":\"9\\/5\\/2013\"},\"6\":\"\",\"14\":[\"61\",\"63\",\"65\"]}}','2014-08-25 02:07:59','2014-08-25 02:07:59','2e555b11-2b38-4db8-9fc3-c100c5f06048'),(45,68,3,1,'en_us',1,'','{\"typeId\":\"3\",\"authorId\":\"1\",\"title\":\"The Urban Crisis: An Unfinished Agenda\",\"slug\":\"the-urban-crisis\",\"postDate\":1408935888,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"2\":\"<p>The time is ripe to revisit the unfinished agenda of the Black Revolt against the urban crisis: What is to be done? The Stop Killer Cops Campaign has a rich yet neglected history from the shooting of black children in Brooklyn in the 1970s to the shooting of Michael Brown in Ferguson in 2014.&nbsp;<\\/p><p>This roundtable of experts will unpack the congested issues of the urban crisis and suggest some current alternatives. Clarence Taylor is a pioneering expert on Civil Rights in the Jim Crow North, writing a book on the history of police brutality in NYC. Junius Williams is a veteran of the Student Nonviolent Coordinating Committee or SNCC and the Students for a Democratic Society or SDS, who pioneered advocacy planning and community development. Mr. Williams will discuss his memoir, Unfinished Agenda: Urban Politics in the Era of Black Power. And, Robert Curvin is a veteran of the Congress of Racial Equality or CORE in Essex County, New Jersey, former dean at the New School & past member of the New York Times editorial board, who has stayed on the cutting edge of alternative community development and economic empowerment from his work at the Ford Foundation to his teaching at Rutgers University. Mr. Curvin will discuss his new book, with an overview of those issues in Inside Newark: Decline, Rebellion, and the Search for Transformation.<\\/p>\",\"13\":[\"19\",\"66\",\"67\"],\"5\":{\"date\":\"9\\/4\\/2014\"},\"6\":\"\",\"14\":\"\"}}','2014-08-25 03:04:48','2014-08-25 03:04:48','8e586641-b2c3-43fb-a069-c0a947def155'),(46,68,3,1,'en_us',2,'','{\"typeId\":\"3\",\"authorId\":\"1\",\"title\":\"The Urban Crisis: An Unfinished Agenda\",\"slug\":\"the-urban-crisis\",\"postDate\":1408935840,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"2\":\"<p>The time is ripe to revisit the unfinished agenda of the Black Revolt against the urban crisis: What is to be done? The Stop Killer Cops Campaign has a rich yet neglected history from the shooting of black children in Brooklyn in the 1970s to the shooting of Michael Brown in Ferguson in 2014.&nbsp;<\\/p><p>This roundtable of experts will unpack the congested issues of the urban crisis and suggest some current alternatives. Clarence Taylor is a pioneering expert on Civil Rights in the Jim Crow North, writing a book on the history of police brutality in NYC. Junius Williams is a veteran of the Student Nonviolent Coordinating Committee or SNCC and the Students for a Democratic Society or SDS, who pioneered advocacy planning and community development. Mr. Williams will discuss his memoir, Unfinished Agenda: Urban Politics in the Era of Black Power. And, Robert Curvin is a veteran of the Congress of Racial Equality or CORE in Essex County, New Jersey, former dean at the New School & past member of the New York Times editorial board, who has stayed on the cutting edge of alternative community development and economic empowerment from his work at the Ford Foundation to his teaching at Rutgers University. Mr. Curvin will discuss his new book, with an overview of those issues in Inside Newark: Decline, Rebellion, and the Search for Transformation.<\\/p>\",\"13\":[\"66\",\"67\",\"19\"],\"5\":{\"date\":\"9\\/4\\/2014\"},\"6\":\"\",\"14\":\"\"}}','2014-08-25 03:05:12','2014-08-25 03:05:12','ca5cf948-094e-4529-a4aa-99ba16a66e9b'),(47,69,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Robert Curvin\",\"slug\":\"robert-curvin\",\"postDate\":1408975194,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Rutgers University, Bloustein School of Planning and Public Policy\",\"10\":\"\",\"9\":\"\",\"11\":\"\",\"12\":\"\",\"8\":\"\"}}','2014-08-25 13:59:54','2014-08-25 13:59:54','6e62b954-7768-4c5e-a604-a58fd9d4a0b3'),(48,70,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Junius Williams\",\"slug\":\"junius-williams\",\"postDate\":1408975322,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Rutgers University Newark\",\"10\":\"\",\"9\":\"\",\"11\":\"\",\"12\":\"\",\"8\":\"\"}}','2014-08-25 14:02:02','2014-08-25 14:02:02','0e82ff04-2a78-4fcc-9db4-0306d2c49bf0'),(49,68,3,1,'en_us',3,'','{\"typeId\":\"3\",\"authorId\":\"1\",\"title\":\"The Urban Crisis: An Unfinished Agenda\",\"slug\":\"the-urban-crisis\",\"postDate\":1408935840,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"2\":\"<p>The time is ripe to revisit the unfinished agenda of the Black Revolt against the urban crisis: What is to be done? The Stop Killer Cops Campaign has a rich yet neglected history from the shooting of black children in Brooklyn in the 1970s to the shooting of Michael Brown in Ferguson in 2014.&nbsp;<\\/p><p>This roundtable of experts will unpack the congested issues of the urban crisis and suggest some current alternatives. Clarence Taylor is a pioneering expert on Civil Rights in the Jim Crow North, writing a book on the history of police brutality in NYC. Junius Williams is a veteran of the Student Nonviolent Coordinating Committee or SNCC and the Students for a Democratic Society or SDS, who pioneered advocacy planning and community development. Mr. Williams will discuss his memoir, Unfinished Agenda: Urban Politics in the Era of Black Power. And, Robert Curvin is a veteran of the Congress of Racial Equality or CORE in Essex County, New Jersey, former dean at the New School & past member of the New York Times editorial board, who has stayed on the cutting edge of alternative community development and economic empowerment from his work at the Ford Foundation to his teaching at Rutgers University. Mr. Curvin will discuss his new book, with an overview of those issues in Inside Newark: Decline, Rebellion, and the Search for Transformation.<\\/p>\",\"13\":[\"66\",\"67\",\"19\"],\"5\":{\"date\":\"9\\/4\\/2014\"},\"6\":\"\",\"14\":[\"69\",\"70\",\"32\"]}}','2014-08-25 14:02:27','2014-08-25 14:02:27','c4603016-e330-4560-8611-cb86667e2f0a'),(50,74,5,1,'en_us',1,'','{\"typeId\":\"8\",\"authorId\":\"1\",\"title\":\"Freedom North: The Black Freedom Struggle in New York\",\"slug\":\"freedom-north-the-black-freedom-struggle-in-new-york\",\"postDate\":1408976487,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"2\":\"\",\"12\":\"\",\"3\":\"\"}}','2014-08-25 14:21:27','2014-08-25 14:21:27','8f53c1c7-d917-421c-9ae7-2032ab71c38f'),(51,74,5,1,'en_us',2,'','{\"typeId\":\"8\",\"authorId\":\"1\",\"title\":\"Freedom North: The Black Freedom Struggle in New York\",\"slug\":\"freedom-north-the-black-freedom-struggle-in-new-york\",\"postDate\":1408976460,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"2\":\"\",\"3\":[\"76\"],\"15\":\"https:\\/\\/www.youtube.com\\/watch?v=3f9_t5BhLKc\"}}','2014-08-25 14:22:46','2014-08-25 14:22:46','09136a10-e8af-4f31-9a67-e1f6f201c4b3'),(52,33,3,1,'en_us',2,'','{\"typeId\":\"3\",\"authorId\":\"1\",\"title\":\"Freedom North: The Black Freedom Struggle in New York\",\"slug\":\"freedom-north\",\"postDate\":1408559640,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"2\":\"\",\"13\":[\"18\",\"19\"],\"5\":{\"date\":\"5\\/2\\/2013\"},\"14\":[\"31\",\"32\"],\"17\":[\"74\"]}}','2014-08-25 14:29:08','2014-08-25 14:29:08','f6e0f73a-5514-4e62-bfe8-9e3b6c5cf068'),(53,78,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"\\u200bAmiri Baraka\",\"slug\":\"amiri-baraka\",\"postDate\":1408997421,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"\",\"10\":\"<p>Amiri Baraka is one of the most respected and widely published African-American writers. With the beginning of Black Civil Rights Movements during the sixties, Baraka explored the anger of African-Americans and used his writings as a weapon against racism. Also, he advocated scientific socialism with his revolutionary inclined poems and aimed at creating aesthetic through them. Amiri Baraka\\u2019s writing career spans over nearly fifty years and has mostly focused on the subjects of Black Liberation and White Racism. He is counted among the few influential political activists who have spent most of their lifetime fighting for the rights of African-Americans.<\\/p>\",\"9\":\"\",\"11\":\"http:\\/\\/www.amiribaraka.com\\/\",\"12\":[\"77\"],\"8\":\"\"}}','2014-08-25 20:10:21','2014-08-25 20:10:21','cd60bd5c-f862-4b63-81e7-3266576be46f'),(54,80,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Ingrid Monson\",\"slug\":\"ingrid-monson\",\"postDate\":1408997659,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Harvard University\",\"10\":\"<p>Dr. Ingrid Monson is the Quincy Jones Professor of Jazz at Harvard and the author of&nbsp;<em>Freedom Sounds: Civil Rights Call out to Jazz and Africa<\\/em>. She has a Ph.D. and an M.A. in Musicology from NYU, and a B.M. from New England Conservatory. Professor Monson won the Sonneck Society\'s 1998 Irving Lowens Prize for the best book in American music for her 1996<em> Saying Something, Jazz Improvisation and Interaction<\\/em>. She was also a founding member of the nationally known Klezmer Conservatory Band, and plays trumpet with jazz and salsa bands. She is working on a book on the music of the&nbsp;African Diaspora.&nbsp;<\\/p>\",\"9\":\"imonson@fas.harvard.edu\",\"11\":\"http:\\/\\/www.music.fas.harvard.edu\\/faculty\\/imonson.html\",\"12\":[\"79\"],\"8\":\"imonson\"}}','2014-08-25 20:14:19','2014-08-25 20:14:19','0964e02d-97b1-4367-af18-793c288458f2'),(55,82,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"John Szwed\",\"slug\":\"john-szwed\",\"postDate\":1408997824,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Columbia University\",\"10\":\"<p>Dr. John Szwed is the Director of Jazz Studies at Columbia where&nbsp;he is also Professor of Music and Jazz Studies and the author&nbsp;of <em>Jazz 101<\\/em>. Dr. Szwed\\u2019s publications range from anthropological&nbsp;studies of Newfoundland and the West Indies to record liner notes&nbsp;and jazz journalism. Before he joined Columbia, Szwed taught&nbsp;Anthropology, African American Studies, and Film Studies for many&nbsp;years at Yale University, and also received fellowships from the&nbsp;Guggenheim and Rockefeller foundations. He is President of&nbsp;the non-profit music production company Brilliant Corners, which&nbsp;is based in New York City.&nbsp;<\\/p>\",\"9\":\"jfs54@columbia.edu\",\"11\":\"http:\\/\\/music.columbia.edu\\/john_szwed\",\"12\":[\"81\"],\"8\":\"\"}}','2014-08-25 20:17:04','2014-08-25 20:17:04','e3966005-eab0-485c-90f5-a3bf7e7a4f60'),(56,86,3,1,'en_us',1,'','{\"typeId\":\"3\",\"authorId\":\"1\",\"title\":\"The Blues People 50 Years Later\",\"slug\":\"the-blues-people\",\"postDate\":1408998085,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"2\":\"<blockquote><p>\\\"Inspired by Amiri Baraka\\u2019s Blues People: Negro Music in White America (1963), a generation of scholars in the field of Jazz and Blues music history and criticism was born, creating a legitimate space in the academy for the serious study of African American music. Joining Amiri Baraka in this conversation-- reflecting on the years between Baraka\\u2019s Blues People and his Digging: The Afro-American Soul of American Music -- will be two major scholars in this field: Ingrid Monson and John Szwed<\\/p><p>Fifty years ago Blues People was the first book-length history written by an African American that addressed the social, musical, economic, and cultural influences of the blues and jazz on American history. His approach to music criticism was different from anything else that existed when he first began writing in the 1950s and 60s, partly because he was the only black writer in a field of white critics. Furthermore, he was not simply describing the music, but he was also fashioning a type of prose writing that was itself an artistic performance about music.\\\"&nbsp;<\\/p><p>-- Komozi Woodard&nbsp;<\\/p><\\/blockquote>\",\"13\":[\"83\",\"84\",\"85\"],\"5\":{\"date\":\"10\\/3\\/2013\"},\"14\":[\"78\",\"80\",\"82\"],\"17\":\"\"}}','2014-08-25 20:21:25','2014-08-25 20:21:25','7dcce639-0230-4943-bc0d-f01be0c80527'),(57,86,3,1,'en_us',2,'','{\"typeId\":\"3\",\"authorId\":\"1\",\"title\":\"The Blues People 50 Years Later\",\"slug\":\"the-blues-people\",\"postDate\":1408998060,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"2\":\"<p>Inspired by Amiri Baraka\\u2019s Blues People: Negro Music in White America (1963), a generation of scholars in the field of Jazz and Blues music history and criticism was born, creating a legitimate space in the academy for the serious study of African American music. Joining Amiri Baraka in this conversation-- reflecting on the years between Baraka\\u2019s Blues People and his Digging: The Afro-American Soul of American Music -- will be two major scholars in this field: Ingrid Monson and John Szwed.<\\/p><p>Fifty years ago Blues People was the first book-length history written by an African American that addressed the social, musical, economic, and cultural influences of the blues and jazz on American history. His approach to music criticism was different from anything else that existed when he first began writing in the 1950s and 60s, partly because he was the only black writer in a field of white critics. Furthermore, he was not simply describing the music, but he was also fashioning a type of prose writing that was itself an artistic performance about music.<\\/p>\",\"13\":[\"83\",\"84\",\"85\"],\"5\":{\"date\":\"10\\/3\\/2013\"},\"14\":[\"78\",\"80\",\"82\"],\"17\":\"\"}}','2014-08-25 20:23:44','2014-08-25 20:23:44','6a354241-8f1b-4c2e-a543-b912d65c3091'),(58,88,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Joshua Guild\",\"slug\":\"joshua-guild\",\"postDate\":1408998413,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Princeton University\",\"10\":\"<p>Joshua B. Guild is an assistant professor who specializes in 20th-century African-American history, with a particular focus on urban communities and the making of the modern African diaspora. Professor Guild\\u2019s dissertation compared African-American and Caribbean migration and politics in the formation of two black communities in post-World War II New York and London. He is currently working on a book based on his dissertation.<\\/p>\",\"9\":\"jguild@princeton.edu \",\"11\":\"http:\\/\\/www.princeton.edu\\/history\\/people\\/display_person.xml?netid=jguild\",\"12\":[\"87\"],\"8\":\"wardellfranklin\"}}','2014-08-25 20:26:53','2014-08-25 20:26:53','00e1efe4-5b70-4476-aac1-9e3a1e18f89b'),(59,90,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Susan Youngblood Ashmore\",\"slug\":\"susan-youngblood-ashmore\",\"postDate\":1408998545,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Emory University\",\"10\":\"<p>Susan Youngblood Ashmore is an American historian with a strong interest in the 20th-century South. Her book <em>Carry It On: The War on Poverty and the Civil Rights Movement in Alabama, 1964-1972<\\/em>, (University of Georgia Press, 2008) examines how the federal anti- poverty programs sponsored by President Lyndon Johnson\'s War on Poverty helped to implement the Civil Rights Act and the Voting Rights Act in the Black Belt of Alabama.<\\/p>\",\"9\":\"sashmor@emory.edu\",\"11\":\"https:\\/\\/app.oxford.emory.edu\\/WebApps\\/Directories\\/index.cfm?fuseaction=v.viewprofile&thisuserid=208&bioNumber=1\",\"12\":[\"89\"],\"8\":\"\"}}','2014-08-25 20:29:05','2014-08-25 20:29:05','efb54d27-0b22-41bf-8301-c599e2f7779b'),(60,92,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Annelise Orleck\",\"slug\":\"annelise-orleck\",\"postDate\":1408998678,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Dartmouth College\",\"10\":\"<p>Dr. Orleck was born and raised in Brooklyn, New York, where you can travel around the world without ever venturing more than a few miles from home. Brooklyn\'s amazing assortment of cultures sparked her interest in the study of history and ethnicity which continues to this day. Her book Storming Caesar\'s Palace traces the lives of nine African- American women born in the Mississippi Delta who became hotel maids, union activists and later welfare rights activists in, of all places, Las Vegas, Nevada.<\\/p>\",\"9\":\"Annelise.Orleck@Dartmouth.edu\",\"11\":\"http:\\/\\/dartmouth.edu\\/faculty-directory\\/annelise-orleck\",\"12\":[\"91\"],\"8\":\"\"}}','2014-08-25 20:31:18','2014-08-25 20:31:18','3167e9c2-9907-4eb3-bf16-c6eb0361928d'),(61,92,4,1,'en_us',2,'','{\"typeId\":\"5\",\"authorId\":\"1\",\"title\":\"Annelise Orleck\",\"slug\":\"annelise-orleck\",\"postDate\":1408998660,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Dartmouth College\",\"10\":\"<p>Dr. Orleck was born and raised in Brooklyn, New York, where you can travel around the world without ever venturing more than a few miles from home. Brooklyn\'s amazing assortment of cultures sparked her interest in the study of history and ethnicity which continues to this day. Her book <em>Storming Caesar\'s Palace<\\/em> traces the lives of nine African-American women born in the Mississippi Delta who became hotel maids, union activists and later welfare rights activists in, of all places, Las Vegas, Nevada.<\\/p>\",\"9\":\"Annelise.Orleck@Dartmouth.edu\",\"11\":\"http:\\/\\/dartmouth.edu\\/faculty-directory\\/annelise-orleck\",\"12\":[\"91\"],\"8\":\"\"}}','2014-08-25 20:31:52','2014-08-25 20:31:52','eadc79f8-9834-4957-afe0-038e3b4cbd23'),(62,94,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Premilla Nadasen\",\"slug\":\"premilla-nadasen\",\"postDate\":1408998958,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Barnard College\",\"10\":\"<p>Dr. Nadasen is associate professor of history at Barnard College. She&nbsp;received her Ph.D. from Columbia University in 1999 and her B.A. from&nbsp;the University of Michigan. Her book <em>Welfare Warriors: The Welfare&nbsp;<\\/em><em>Rights Movement in the United States <\\/em>(2005) outlines the ways in&nbsp;which African-American women on welfare forged a feminism of their&nbsp;own out of the political and cultural circumstances of the late 1960s&nbsp;and 1970s.<\\/p>\",\"9\":\"pnadasen@barnard.edu\",\"11\":\"https:\\/\\/barnard.edu\\/profiles\\/premilla-nadasen\",\"12\":[\"93\"],\"8\":\"premillanadasen\"}}','2014-08-25 20:35:58','2014-08-25 20:35:58','820319a3-f482-4724-99df-46256c8b6aae'),(63,98,3,1,'en_us',1,'','{\"typeId\":\"3\",\"authorId\":\"1\",\"title\":\"The War on Poverty and The Struggle for Welfare Rights\",\"slug\":\"poverty-and-welfare\",\"postDate\":1408999172,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"2\":\"<p>\\\"Economic justice and welfare rights sat at the heart of many Black&nbsp;freedom struggles. Yet, until recently, these campaigns have not&nbsp;received the historical attention they have deserved. Poor&nbsp;people&mdash;and poor Black mothers in particular&mdash;reshaped notions of&nbsp;rights, dignity, and citizenship in struggles across the country.&nbsp;They redefined militancy and self-determination, insisting that&nbsp;public assistance and economic access were a key to a free Black&nbsp;people. These grassroots struggles led President Lyndon Johnson\'s&nbsp;to declare a federal commitment to a War on Poverty. While that&nbsp;war was under-resourced and dwarfed by the War in Vietnam,&nbsp;people across the country fought to make programs responsive to&nbsp;the needs and perspectives of the poor as well as the privileged.&nbsp;Join us for a timely discussion as four scholars discuss how&nbsp;grassroots campaigns for welfare rights and economic justice,&nbsp;sought to make the federal government accountable to poor&nbsp;people and the successes and limitations of the War on Poverty&nbsp;programs that were created.\\\" -- Jeanne Theoharis<\\/p>\",\"13\":[\"95\",\"96\",\"97\"],\"5\":{\"date\":\"11\\/7\\/2013\"},\"14\":[\"90\",\"94\",\"92\"],\"17\":\"\"}}','2014-08-25 20:39:32','2014-08-25 20:39:32','1f4e1ae4-2372-49f3-838a-09d6e92a6e5b'),(64,100,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Devorah Heitner\",\"slug\":\"devorah-heitner\",\"postDate\":1409000713,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"\",\"10\":\"\",\"9\":\"\",\"11\":\"http:\\/\\/blackpowertv.com\\/\",\"12\":[\"99\"],\"8\":\"DevorahHeitner\"}}','2014-08-25 21:05:13','2014-08-25 21:05:13','433a7ec5-f245-4f1d-9295-c68dd5f72055'),(65,102,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Madeline Anderson\",\"slug\":\"madeline-anderson\",\"postDate\":1409000826,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"\",\"10\":\"\",\"9\":\"\",\"11\":\"\",\"12\":[\"101\"],\"8\":\"\"}}','2014-08-25 21:07:06','2014-08-25 21:07:06','395f01c7-822d-4229-ae90-f095adc8ac35'),(66,104,3,1,'en_us',1,'','{\"typeId\":\"3\",\"authorId\":\"1\",\"title\":\"Black Power TV\",\"slug\":\"black-power-tv\",\"postDate\":1409000908,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"2\":\"<p>\\u201cOn December 5, Conversations in Black Freedom Studies will present <em style=\\\"font-family: Arial, Helvetica, Verdana, Tahoma, sans-serif; font-size: 14px; background-color: initial;\\\">Black Power TV<\\/em> author Devorah Heitner in a discussion on the rise of African-American public television: New York\\u2019s <em style=\\\"font-family: Arial, Helvetica, Verdana, Tahoma, sans-serif; font-size: 14px; background-color: initial;\\\">Inside Bedford-Stuyvesant<\\/em> and Boston\\u2019s <em style=\\\"font-family: Arial, Helvetica, Verdana, Tahoma, sans-serif; font-size: 14px; background-color: initial;\\\">Say Brother<\\/em>, as well as Black America\\u2019s <em>So<\\/em><em>ul<\\/em><em>! <\\/em>& <em style=\\\"font-family: Arial, Helvetica, Verdana, Tahoma, sans-serif; font-size: 14px; background-color: initial;\\\">Black Journal<\\/em>.  Her special guest will be Madeline Anderson.  After making the 1963 film <em style=\\\"font-family: Arial, Helvetica, Verdana, Tahoma, sans-serif; font-size: 14px; background-color: initial;\\\">The Cool World <\\/em>Madeline Anderson worked on <em style=\\\"font-family: Arial, Helvetica, Verdana, Tahoma, sans-serif; font-size: 14px; background-color: initial;\\\">Black Journal<\\/em>, including the 1969 \\u201cA Tribute to Malcolm.\\u201d In 1978, she became the first African American woman to produce a nationally broadcast television series, <em style=\\\"font-family: Arial, Helvetica, Verdana, Tahoma, sans-serif; font-size: 14px; background-color: initial;\\\">The Infinity Factory.\\u201d&nbsp;<\\/em>--&nbsp;Komozi Woodard&nbsp;<\\/p>\",\"13\":[\"103\"],\"5\":{\"date\":\"12\\/5\\/2013\"},\"14\":[\"100\",\"102\"],\"17\":\"\"}}','2014-08-25 21:08:28','2014-08-25 21:08:28','e2e33407-1fe3-4392-9901-6804c5ab0288'),(67,104,3,1,'en_us',2,'','{\"typeId\":\"3\",\"authorId\":\"1\",\"title\":\"Black Power TV\",\"slug\":\"black-power-tv\",\"postDate\":1409000880,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"2\":\"<p>\\u201cOn December 5, Conversations in Black Freedom Studies will present <em>Black Power TV<\\/em> author Devorah Heitner in a discussion on the rise of African-American public television: New York\\u2019s <em>Inside Bedford-Stuyvesant<\\/em> and Boston\\u2019s <em>Say Brother<\\/em>, as well as Black America\\u2019s <em>So<\\/em><em>ul<\\/em><em>! <\\/em>& <em>Black Journal<\\/em>.  Her special guest will be Madeline Anderson.  After making the 1963 film <em>The Cool World <\\/em>Madeline Anderson worked on <em>Black Journal<\\/em>, including the 1969 \\u201cA Tribute to Malcolm.\\u201d In 1978, she became the first African American woman to produce a nationally broadcast television series, <em>The Infinity Factory.\\u201d&nbsp;<\\/em>--&nbsp;Komozi Woodard&nbsp;<\\/p>\",\"13\":[\"105\"],\"5\":{\"date\":\"12\\/5\\/2013\"},\"14\":[\"100\",\"102\"],\"17\":\"\"}}','2014-08-25 21:09:58','2014-08-25 21:09:58','69eae109-3f02-4fad-ac45-aaf47173963a'),(68,107,2,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Announcement: Summer 2015 Seminar\",\"slug\":\"summer-2015\",\"postDate\":1409001488,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"2\":\"<h1>Rethinking Black Freedom Studies in the Jim Crow North<\\/h1><p>Deadline: March 2, 2015<br>\\r\\nDates: June 15-June 26 (2 weeks)<br>\\r\\nProject Director(s): Komozi Woodard, Sarah Lawrence College, and Jeanne Theoharis, Brooklyn College, CUNY<br>\\r\\nLocation: Bronxville, NY<br>\\r\\nFor more information: kwoodard@sarahlawrence.edu <span id=\\\"gc-number-1\\\" class=\\\"gc-cs-link\\\" title=\\\"Call with Google Voice\\\">(914) 395-2427<\\/span><\\/p><p>Supported by a grant from the National Endowment of the Humanities<\\/p><p>Many faculty working in this area, particularly younger scholars, would like to deepen their knowledge of this burgeoning field of study as well as work on their own scholarship in the company of others versed in the subject.  Thus, the time is ripe to reform the college curriculum on the Black Freedom Struggle and to convene a summer workshop specifically devoted to producing scholarship in this area.<\\/p><p>For decades the academic disciplines focused exclusively on the history of the Civil Rights struggle in the Jim Crow South, neglecting the rich and critical legacy of the Black Freedom struggle from the Jim Crow North to the Jim Crow West.  This seminar would introduce the emerging paradigm in Black Freedom Studies that is replacing the old master narrative in terms of leadership, geography, chronology, economy, and polity.<\\/p><p>The old paradigm of Civil Rights as an exclusively Southern history and Black Power as a predominantly Northern phenomenon has been powerfully challenged by a new generation of scholarship that analyzes the Civil Rights & Black Power movements in several regions and<em>numerous<\\/em> locations in the United States. The old North-South and Civil Rights-Black Power dichotomies blinded scholars to serious problems in the logic of geography, chronology, economy and policy, as well as stories of leadership and culture that blended approaches. In fact, similar to the lives of many of the activists who worked in both the South and North, the story is intertwined.  For instance, the 1950s Montgomery Bus Boycott was preceded by the Harlem Bus Boycott of the 1940s.  Angered by the bus boycott and Northern hypocrisy, the <em>Montgomery Advertiser<\\/em>, the main Montgomery newspaper, took to running articles during the boycott year on Northern towns with attitudes and practices similar to Montgomery.  Rosa Parks herself was forced to leave Montgomery and moved to Detroit&mdash;\\u201cthe promised land that wasn\\u2019t\\u201d as she termed it&mdash;where she would spend the second half of her life challenging racial inequality in the city. Yet, in the old master narrative, that half of her life was historically invisible.<\\/p><p>One longstanding key issue is school segregation.  In fact, segregated education has longer roots in the Jim Crow North, where civil rights activists and abolitionists fought the exclusion and segregation of black students beginning decades before the Civil War.  From New York and Canterbury to Boston and New Canaan, New Hampshire, blacks and whites were schooled separately, and those who dared to create interracial spaces were often met with violence.  Between Independence Day and Labor Day in 1835, white mobs in New Canaan attacked the interracial Noyes Academy, bringing a number of oxen in order to pull the school off its foundation and dump it into a swamp. Similarly, white mobs stormed out of church in order to attack Prudence Crandall\\u2019s interracial girls-academy in Canterbury, Connecticut; and the Quaker Prudence Crandall was imprisoned and exiled for the crime of educating Black girls.  In Boston, parents and abolitionists attacked educational segregation in the courts, starting a legal history that runs through the 1896 <em>Plessy<\\/em> v. <em>Ferguson<\\/em> Supreme Court decision to the 1955 <em>Brown<\\/em> <em>v.<\\/em> <em>Board<\\/em> of Education II Supreme Court decision and into the 1970s Boston Busing Crisis.<\\/p><p>Similarly, in the Jim Crow West, Donna Murch discovered a decisive linkage between the public education for African Americans migrants and the massive development of the California juvenile detention system. In other words, the children of Black migrants, particularly the boys, were socialized in a new juvenile version of the penal system, which Murch suggests is part of the hidden transcript of the Black Revolt in the Jim Crow West.  Was there a similar linkage between the public school crisis, juvenile detention systems, and rising Black Power movements in the Jim Crow North and the Jim Crow Midwest? Such issues are part of the new research agenda developing in Black Freedom Studies as scholars look at Philadelphia, New York, Boston, Detroit and Chicago with new eyes.<\\/p><p>Thus, the research agenda for Black Freedom Studies has changed dramatically not only in terms of public policy issues but also geography and chronology in order to understand the roots and branches of Jim Crow America.  The racism found in the North was presumed to be a weak transplant from the South, not rooted in the systems and power structures <em>beyond the South<\\/em>&mdash;but as scholars have amply shown, that view was resoundingly mistaken and the problem was deeply entrenched in the structures and systems of Northern municipal governance, schooling, housing policy, and policing. Consequently, scholars have discovered that the Black Revolt in the Jim Crow North challenged American Apartheid not only in education and real estate but also in governance and the administration of justice.<\\/p><p>If the old paradigm emphasized cultural poverty in the Jim Crow North, then the new scholarship tracing Northern racial discrimination from colonial slavery to the 1960s foregrounds the real estate and banking industries as well as housing and job markets not behaviors and family structure as the key determinant to Black ghetto life. Meanwhile, the burgeoning research in cultural history has enriched our understanding of the New Negro Movement, the Harlem Renaissance, the Chicago Black Renaissance, and the Black Arts Renaissance; and that formidable cultural and social history supplants the threadbare theory of cultural poverty. If cultural poverty was <em>not <\\/em>the problem of the Jim Crow North, then what was the problem?  The new scholarship suggests the answers are located in public policy and political economy from the New Deal to the Cold War, including works such as Ira Katznelson\\u2018s <em>When Affirmative Action Was White<\\/em> and Mary Poole\\u2018s <em>The Segregated Origins of Social Security,<\\/em> as well as Thomas Sugrue\\u2018s <em>The Origins of the Urban Crisis<\\/em> and <em>Sweet Land of Liberty<\\/em>.  The New Deal transformed Social Citizenship propelling many white working households from renting urban tenements to suburban homeownership, providing GI Bill scholarships to turn workers into professionals and technicians.  By contrast, those same programs routinely excluded Black America from the bounty of New Deal Citizenship.<\\/p><p>Above all, the new history informs us that countless grassroots leaders fought their own War on Poverty. In <em>The Business of Black Power<\\/em>, Laura Hill and Julia Rabig have gathered stories of tenant leaders and welfare activists who developed a remarkable number of affordable housing units in Newark, New Jersey; unemployed workers who fought for construction jobs in Chicago, Philadelphia and Pittsburgh; and Black youth organizations that opened their own independent schools with new curricula emphasizing science and math.  Moreover, scholars found the same pattern of history from Las Vegas to Baltimore.  In <em>Storming Caesars Palace: How Black Mothers Fought their Own War on Poverty<\\/em>, Annelise Orleck tells the stories of the remarkable grassroots leaders that transformed communities in Las Vegas; and in <em>The Politics of Public Housing: Black Women\\u2019s Struggles Against Urban Inequality,<\\/em> Rhonda Williams reveals the impressive accounts of the grassroots housing reforms in Baltimore shaped by tenant organizations. This inspiring work has enriched and complicated the narrative of Civil Rights and Black Power, making the cultural poverty narrative nearly implausible.<\\/p><p>The new scholarship&mdash;which we will survey in this two-week seminar&mdash; paints an epic portrait of the Black Freedom Movement, where important ideas and impressive programs of self-emancipation and self-respect circulated in the Jim Crow North between Philadelphia and Boston, in the Jim Crow Midwest between Detroit and Milwaukee, and in the Jim Crow West between Oakland and Los Angeles&mdash;not to mention, the cross-fertilization of ideas like the bus boycotts that occurred between the North and South.<\\/p><p>We will ask each participant to bring an article-length portion of their project to work on and workshop over the two weeks.  Certain days, we will meet at the Schomburg Center so that part of the seminar will include time for researching in those collections and meeting with Schomburg staff.  Most projects on the Black freedom struggle require resources from the Schomburg\\u2019s vast archival collections so this will be an added benefit of locating the seminar in New York City.<\\/p><p>The project website will house not only syllabi but also lesson plans and the visual library outlined above and other books and articles suggested by the participants.  At the end of the seminar we will have a rich bibliography online so that other professors, teachers, and students can draw from it.  The website will be designed so that teachers and professor may also stream videos of Conversations on Black Freedom Studies and the International Symposium on Black Power Studies. Such scholarly conversations should be helpful to teachers and professors who are developing curriculum and lessons in this field. Furthermore, we hope to pull together an anthology out of the work produced in the seminar.  Our editor is eager for more work in the field and we have worked with her on our previous three anthologies.<\\/p><h2>Program of Study<\\/h2><p>The seminar will be held the last two weeks of June.  Many professors use June for their own research and July-August for family vacations&mdash;which is why we want to schedule it in June. Also, the Sarah Lawrence College facilities are available during that period.<\\/p><p>The heart of this two-week seminar is to advance the historiography and scholarship of the participants who are writing and teaching in Black Freedom Studies. And, the seminar aims to strengthen the teachable texts in the field; thus, the workshop method that we will employ emphasizes the linkage between teaching and writing. The participating scholars will examine the seminar readings, at one level unpacking the contributions of the writing in terms of argument, propositions and organizational design as well as narrative, plot and character development.  At another level, discussion will also focus on analyzing gaps or flaws in the research or analysis or places where further research or analysis might be warranted.<\\/p><p>The seminar will incorporate readings in the field and participant writing workshops, research and informational sessions, as well as discussion of processes from research to publication.  Once selected and before the seminar begins, each participant will also suggest one article or chapter that is a model for the kind of research, analysis, or approach that s\\/he is working towards that will be incorporated into the recommended readings for the seminar.  Each session will encompass readings in the field and work-shopping.  We will also interspace workshops on the writing process itself and bring in various guest lecturers.<\\/p><p>In turn, seminar participants will exchange drafts and present evaluations of the effectiveness of each person\\u2019s writing in terms of argument, propositions and organizational design as well as narrative development; then they will suggest improvements with editorial recommendations.<\\/p>\",\"3\":\"\"}}','2014-08-25 21:18:08','2014-08-25 21:18:08','8aed825f-2315-461e-8f00-db222096e379'),(69,108,7,1,'en_us',1,'','{\"typeId\":\"10\",\"authorId\":null,\"title\":\"About\",\"slug\":\"about\",\"postDate\":1409001739,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"2\":\"<p>Conversations in Black Freedom Studies is a monthly roundtable discussion at the Schomburg Center with authors and experts in Black history.&nbsp;Held on the first Thursday of every month from&nbsp;6-8 pm, these conversations focus on a theme --from the Jim Crow North to the Black Panther Party, from educational inequality to the Black Arts Movement.   They are geared for New York City teachers, parents, students, scholars, activists, and policy-makers. Black Freedom Studies has introduced a new paradigm for research and scholarship on the long Black revolt, challenging older conceptions of geography, leadership, ideology, culture and chronology to deepen popular understandings of the scope of the Black freedom struggle. With the closing of a number of black bookstores, there are fewer spaces where a diversity of people can gather to hear and discuss new scholarship in African American history.&nbsp;CBFS aims to begin to fill that need.&nbsp;<\\/p><p>The following text is from the original proposal for CBFS.<\\/p><p>This would be a series of roundtable discussions with authors and experts in Black Freedom Studies that might culminate in a Black Power Studies Symposium aimed at New York City teachers, parents and students alongside scholars, educators and policy-makers. Black Freedom Studies has introduced a new paradigm for research and scholarship on the Long Black Revolt, challenging the older geography, leadership, ideology, culture and chronology of Civil Rights historiography. If we record and videotape these conversations, then several publications and references might be produced to support teachers, parents and students a mass education and self-education initiative. And the aim is the help our communities identify, explore, appreciate, develop, and master their own phenomenal human resources, including their wealth in the kind of imaginative power that makes history.<\\/p><p>These conversations might capture several dimensions of the new scholarship, including these: 1) an intergenerational time frame; 2) grassroots intellectual tradition; 3) Black Arts Renaissance and Jazz Revolution; 4) self-governance and public policy; 5) Black Power at Work and the Business of Black Power; 6) the genius of Women\\u2019s Leadership and the Stamina of the Organizing Tradition; 7) Rethinking Malcolm X historiography and legacy; and 8) Harlem politics at the center of Black Internationalism.<\\/p><p>One dimension is the significance of the intergenerational findings that have emerged in the research. In other words, the new paradigm suggests a dramatically different chronology in Black Freedom Studies, including at least two generations. For instance, Amiri Baraka\\u2019s mentors included not only Sterling Brown and Margaret Walker from the Popular Front generation but also Langston Hughes from the Harlem Renaissance.<\\/p><p>Second, another aspect of Black Freedom Studies is the importance of the Harlem Grassroots Intellectual Tradition. In other words, for far too long we have neglected Malcolm X as a working-class intellectual alongside the fact that Malcolm X was representative of a grassroots intellectual tradition that predated Antonio Gramsci. The work on Hubert Harrison, the Socrates of the Harlem Renaissance, and the use of the Negro World as a vehicle for a mass self-education movement provides another important window into that grand Harlem tradition. That tradition of mass self-education was the groundwork for the \\u201c<em>Each One Teach One<\\/em>\\u201d practices in the Black Arts Renaissance and the Black Power Movement with its countless liberation schools, student study circles, museum, libraries and salons. These discussions may be helpful to teachers, parents and students facing the challenges of austerity policies.<\\/p><p>A third dimension of Black Freedom Studies is the promising emphasis on culture, centering on the Black Arts Renaissance. <em>Ironically, Harlem has been grossly neglected in the new Black Arts Movement scholarship.<\\/em> And that neglect is distorting the contours of that research. We should take advantage of the pioneers and veterans of the Black Arts Renaissance in Harlem that remain available for roundtable discussions. If those conversations are recorded they might serve as primary sources for the scholarship to come. Sam Anderson, Jitu Weusi, Ted Wilson, Amiri Baraka, Sonia Sanchez are close at hand. And we should take the opportunity to consider the Nuyorican Arts Renaissance that flowered at times alongside and at times within the bosom of the Black Arts Movement. Felipe Luciano can shed light on the working of the Last Poets from that vantage point; and of course, the rest of the remaining Last Poets should be at the center of such a roundtable. Furthermore, Askia Toure is not far away and he was also a pioneer in the Black Arts Movement alongside Lou Gossett and so forth. Harlem was the home of Langston Hughes who seems to have cultivated the groundwork for many features of the Black Arts Renaissance, including its international character. And thus far we have neglected important figures like Elombe Brath who political and cultural work in black culture and consciousness began to flower in the 1950s, attracting many African liberation leaders to the bosom of Harlem. In fact, next year will mark the 50<sup>th<\\/sup> anniversary of the publication of <em>Blues People<\\/em>; and when I organized the 40<sup>th<\\/sup> anniversary symposium at Sarah Lawrence College the response was overwhelming.<\\/p><p>A fourth aspect of Black Freedom Studies in the importance of political activism and public policy alternatives in the Black Revolt in the Jim Crow North. Johanna Fernandez has highlighted the way that the Young Lords used mass media to dramatize long dormant public policy problems like lead paint to make crucial changes. Of course, the Young Lords were \\u201cin the tradition\\u201d of SNCC and the Civil Rights Revolution. And we could not miss an opportunity to talk about Brooklyn and the Bronx CORE and so forth. From the citizenship schools to the liberation schools, Black Power aimed to train generations in not only self-worth but also self-governance.<\\/p><p>A fifth characteristic of Black Freedom Studies its attention to economic struggles, captured in several anthologies such as <em>The Business of Black Power<\\/em> and <em>Black Power at Work<\\/em>. In many ways, this is the case of the genius of Black Labor that remains untold. Furthermore, we might also consider the rekindled debates about the nature of internal colonialism in that venue.<\\/p><p>A sixth feature of Black Freedom Studies is strategic importance of women\\u2019s leadership and the organizing tradition. And there is some phenomenal new work on that subject, including not only <em>Sisters in the Struggle<\\/em> but also <em>Want to Start A Revolution: Radical Women in the Black Freedom Struggle?<\\/em><\\/p><p>A seventh aspect of Black Freedom Studies is rethinking Malcolm X. Given the controversy and Pulitzer Prize for Manning Marable\\u2019s recent biography, there is no shortage of important discussion on this subject. Of course, Malcolm X is at the center of rethinking Black Power; so the conversations that fashion some basic intellectual consensus on that research agenda is essential. With the Malcolm X papers at hand, there is no place better suited for such conversations than the Schomburg.<\\/p><p>An eighth dimension is that of Black Internationalism and no community is better positioned than Harlem to appreciate the fact that the local is also simultaneously international. Michael West edited <em>From Toussaint to Tupac: The Black International Since the Age of Revolution<\\/em>. Brent Hayes Edwards has made a major contribution in <em>The Practice of Diaspora: Literature, Translation, and the Rise of Black Internationalism<\\/em>. And Tyler Stovall complements that conversation with <em>Paris Noir: African Americans in the City of Light<\\/em>.<\\/p><p>Finally, since this is the fortieth anniversary of the 1972 Gary Agenda, we might consider some public policy and self-governance conversations about the contours of the National Black Agenda then and now, including the Harlem Agenda for 2012 and the future.<\\/p>\"}}','2014-08-25 21:27:23','2014-08-25 21:27:23','de9ddfdf-7502-497e-8440-c6dbe8a442bf'),(70,2,1,1,'en_us',3,'','{\"typeId\":\"1\",\"authorId\":null,\"title\":\"Homepage\",\"slug\":\"homepage\",\"postDate\":1408482960,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"2\":\"<p>The Schomburg Center for Research in Black Culture brings the campus to the community for a series of roundtable conversations on the first Thursday of each month. This series is curated by Professors <a href=\\\"http:\\/\\/craft.blackfreedomstudies.org\\/speakers\\/jeanne-theoharis#entry:41\\\">Jeanne Theoharis<\\/a> (Brooklyn College\\/CUNY) and <a href=\\\"http:\\/\\/craft.blackfreedomstudies.org\\/speakers\\/komozi-woodard#entry:45\\\">Komozi Woodard<\\/a> (Sarah Lawrence College), and introduces a new paradigm that challenges the older geography, leadership, ideology, culture and chronology of Civil Rights historiography. A special reading list has been compiled by series, and conversations will be videotaped and made available for public viewing at the Schomburg library. We encourage adult learners, educators and college students to join us each month for this dynamic learning experience!<\\/p>\",\"1\":\"Conversations in Black Freedom Studies\"}}','2014-08-25 21:33:02','2014-08-25 21:33:02','64dec937-a2d5-4309-b7bc-6285118eeb86'),(71,2,1,1,'en_us',4,'','{\"typeId\":\"1\",\"authorId\":null,\"title\":\"Homepage\",\"slug\":\"homepage\",\"postDate\":1408482960,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"2\":\"<p>The Schomburg Center for Research in Black Culture brings the campus to the community for a series of roundtable conversations on the first Thursday of each month. This series is curated by Professors <a href=\\\"http:\\/\\/craft.blackfreedomstudies.org\\/speakers\\/jeanne-theoharis#entry:41:url\\\">Jeanne Theoharis<\\/a> (Brooklyn College\\/CUNY) and <a href=\\\"http:\\/\\/craft.blackfreedomstudies.org\\/speakers\\/komozi-woodard#entry:45:url\\\">Komozi Woodard<\\/a> (Sarah Lawrence College), and introduces a new paradigm that challenges the older geography, leadership, ideology, culture and chronology of Civil Rights historiography. A special reading list has been compiled by series, and conversations will be videotaped and made available for public viewing at the Schomburg library. We encourage adult learners, educators and college students to join us each month for this dynamic learning experience!<\\/p><p><img src=\\\"http:\\/\\/craft.blackfreedomstudies.org\\/images\\/archive\\/_fullWidth\\/Schomburg-Logo.png#asset:109:fullWidth\\\" alt=\\\"\\\" style=\\\"display: block; margin: auto;\\\"><\\/p>\",\"1\":\"Conversations in Black Freedom Studies\"}}','2014-08-26 01:58:50','2014-08-26 01:58:50','929a2d03-4020-4779-88f5-28843d63845a'),(72,111,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Craig Steven Wilder\",\"slug\":\"craig-steven-wilder\",\"postDate\":1409190257,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Massachusetts Institute of Technology\",\"10\":\"<p>Craig Steven Wilder studies American urban, intellectual, and cultural history. Professor Wilder\\u2019s most recent book is <em style=\\\"font-family: Arial, Helvetica, Verdana, Tahoma, sans-serif; font-size: 14px; background-color: initial;\\\">Ebony & Ivy: Race, Slavery, and the Troubled History of America\\u2019s Universities&nbsp;<\\/em>(New York: Bloomsbury, 2013).  Dr. Wilder began his career as a community organizer in the South Bronx.  He provides curricular and professional development workshops with public school teachers in low-income areas of New York City.  Professor Wilder is a senior fellow at the&nbsp;<a href=\\\"http:\\/\\/vimeo.com\\/47115041\\\" style=\\\"font-family: Arial, Helvetica, Verdana, Tahoma, sans-serif; font-size: 14px; background-color: initial;\\\">Bard Prison Initiative<\\/a>, this innovative program has given hundreds of men and women the opportunity to acquire a college education during their incarcerations in the New York State prison system.<\\/p>\",\"9\":\"cwilder@mit.edu\",\"11\":\"http:\\/\\/history.mit.edu\\/people\\/craig-s-wilder\",\"12\":[\"110\"],\"8\":\"craigswilder\"}}','2014-08-28 01:44:17','2014-08-28 01:44:17','50e7059c-66ed-4c41-bf5b-f81f1ac61550'),(73,113,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"\\u200bAnsley T. Erickson\",\"slug\":\"ansley-t.-erickson\",\"postDate\":1409190440,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Teachers College Columbia University\",\"10\":\"<p>Ansley T. Erickson is a historian who focuses on educational inequality and the interaction between schooling, urban and metropolitan space, and economic change. She earned her Ph.D. in U.S. History from Columbia University in May, 2010. Her manuscript in progress,<em style=\\\"font-family: Arial, Helvetica, Verdana, Tahoma, sans-serif; font-size: 14px; background-color: initial;\\\"><a href=\\\"http:\\/\\/www.tc.columbia.edu\\/academics\\/upload\\/ate11\\/Erickson_TitlePage&Abs_DEP.pdf\\\">Schooling the Metropolis: Educational Inequality Made and Remade<\\/a><\\/em>reveals how private and public agendas for economic growth and spatial transformations in the city shaped educational inequality by race and class, through an examination of the case of Nashville, Tennessee. Dr, Erickson also leads the Educating Harlem Project.<\\/p>\",\"9\":\"erickson@tc.columbia.edu\",\"11\":\"http:\\/\\/www.tc.columbia.edu\\/academics\\/?facid=ate11\",\"12\":[\"112\"],\"8\":\"\"}}','2014-08-28 01:47:20','2014-08-28 01:47:20','2b4363d7-237d-4373-ac51-0273c596e74b'),(74,115,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Jonna Perrillo\",\"slug\":\"jonna-perrillo\",\"postDate\":1409190748,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"The University of Texas at El Paso\",\"10\":\"<p>Dr. Perrillo is assistant professor of English Education and formerly directed the West Texas Writing Project from 2005 to 2011. She received her Ph.D. in Teaching and Learning from New York University in 2005, where she was trained in both English Education and education history methods. Dr. Perrillo\\u2019s book <em style=\\\"font-family: Arial, Helvetica, Verdana, Tahoma, sans-serif; font-size: 14px; background-color: initial;\\\">Uncivil Rights: Teachers, Unions, and Race in the Battle for School Equity<\\/em> (University of Chicago Press, 2012) examines the ways in which teachers and civil rights activists both collaborated and conflicted with each other in their efforts to reform public schools and the teaching profession from the 1920s to now.<\\/p>\",\"9\":\"jperrillo@utep.edu\",\"11\":\"http:\\/\\/academics.utep.edu\\/Default.aspx?tabid=32729\",\"12\":[\"114\"],\"8\":\"\"}}','2014-08-28 01:52:28','2014-08-28 01:52:28','597de601-42c2-473f-891b-5b49cc596788'),(75,118,3,1,'en_us',1,'','{\"typeId\":\"3\",\"authorId\":\"1\",\"title\":\"Slavery, White Supremacy, and Struggle in American Education\",\"slug\":\"slavery-white-supremacy-and-struggle-in-american-education\",\"postDate\":1409190871,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"2\":\"<p>\\\"From the beginning of America, the promise of equality in education was mutilated by the barbarism and profiteering of the Slave Trade. And from the very beginning, African Americans contested school inequity and academic justifications for racial inequality.  Learn about the tragic history of slavery on early American college campuses and the struggles for educational justice and desegregation in Nashville and New York.  Join us as we discuss two recent important books <em>Ebony and Ivy: Race, Slavery, and the Troubled History of America\'s Universities<\\/em> and <em>Uncivil Rights: Teachers, Unions and Race in the Battle for School Equity <\\/em>with Craig Steven Wilder, Ansley Erickson, and Jonna Perrilloand how this history informs our struggles for educational justice and equality today.\\\"<\\/p><p><em style=\\\"font-family: Arial, Helvetica, Verdana, Tahoma, sans-serif; font-size: 14px; background-color: initial;\\\">--Komozi Woodard<\\/em><\\/p>\",\"13\":[\"117\",\"116\"],\"5\":{\"date\":\"2\\/6\\/2014\"},\"14\":[\"111\",\"113\",\"115\"],\"17\":\"\"}}','2014-08-28 01:54:31','2014-08-28 01:54:31','59ea6775-4152-4c76-98b3-6b38ee031b73'),(76,119,3,1,'en_us',1,'','{\"typeId\":\"6\",\"authorId\":\"1\",\"title\":\"Spring 2014\",\"slug\":\"spring-2014\",\"postDate\":1409190886,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"2\":\"\"}}','2014-08-28 01:54:46','2014-08-28 01:54:46','98bf02ae-a653-4415-92f3-784a1489909b'),(77,121,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Mary Phillips\",\"slug\":\"mary-phillips\",\"postDate\":1409191233,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Lehman College CUNY\",\"10\":\"\",\"9\":\"Mary.Phillips@lehman.cuny.edu\",\"11\":\"\",\"12\":[\"120\"],\"8\":\"\"}}','2014-08-28 02:00:33','2014-08-28 02:00:33','610250a5-1318-4b2f-abe2-64ec80dabc82'),(78,123,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Sherie Randolph\",\"slug\":\"sherie-randolph\",\"postDate\":1409191310,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"University of Michigan\",\"10\":\"\",\"9\":\"smrand@umich.edu\",\"11\":\"http:\\/\\/www.lsa.umich.edu\\/history\\/people\\/faculty\\/ci.randolphsherie_ci.detail\",\"12\":[\"122\"],\"8\":\"\"}}','2014-08-28 02:01:50','2014-08-28 02:01:50','8cf790a5-e66f-4756-ab16-5670e105e89b'),(79,125,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Emilye Crosby\",\"slug\":\"emilye-crosby\",\"postDate\":1409191441,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"SUNY Geneseo\",\"10\":\"\",\"9\":\"crosby@geneseo.edu\\t\",\"11\":\"http:\\/\\/www.geneseo.edu\\/history\\/emilye-crosby\",\"12\":[\"124\"],\"8\":\"\"}}','2014-08-28 02:04:01','2014-08-28 02:04:01','71676dcf-437d-4b74-a385-50208af96a61'),(80,128,3,1,'en_us',1,'','{\"typeId\":\"3\",\"authorId\":\"1\",\"title\":\"Sisters in the Struggle: Sustaining Black Women\\u2019 Emancipation from Racism, Sexism and Violence\",\"slug\":\"sisters-in-the-struggle-sustaining-black-women-emancipation-from-racism-sexism-and-violence\",\"postDate\":1409191718,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"2\":\"\",\"13\":[\"127\",\"126\"],\"5\":{\"date\":\"3\\/6\\/2014\"},\"14\":[\"12\",\"121\",\"125\"],\"17\":\"\"}}','2014-08-28 02:08:38','2014-08-28 02:08:38','07d62151-41e6-4dce-bf2f-28c016497c6c'),(81,128,3,1,'en_us',2,'','{\"typeId\":\"3\",\"authorId\":\"1\",\"title\":\"Sisters in the Struggle: Sustaining Black Women\\u2019 Emancipation from Racism, Sexism and Violence\",\"slug\":\"sisters-in-the-struggle-sustaining-black-women-emancipation-from-racism-sexism-and-violence\",\"postDate\":1409191680,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"2\":\"\",\"13\":[\"127\",\"126\"],\"5\":{\"date\":\"3\\/6\\/2014\"},\"14\":[\"12\",\"121\",\"125\",\"123\"],\"17\":\"\"}}','2014-08-28 02:09:09','2014-08-28 02:09:09','8d6d0754-8da7-4458-954e-c068879acb4e'),(82,130,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Carl Nightingale\",\"slug\":\"carl-nightingale\",\"postDate\":1409192160,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"University of Buffalo\",\"10\":\"\",\"9\":\"cn6@buffalo.edu\",\"11\":\"http:\\/\\/transnationalstudies.buffalo.edu\\/faculty\\/nightingale.shtml\",\"12\":[\"129\"],\"8\":\"\"}}','2014-08-28 02:16:00','2014-08-28 02:16:00','a31aa03a-6674-4567-8290-06e81d991a49'),(83,132,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Karen Miller\",\"slug\":\"karen-miller\",\"postDate\":1409192334,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Laguardia Community College CUNY\",\"10\":\"\",\"9\":\"kamiller@lagcc.cuny.edu\",\"11\":\"http:\\/\\/www.lagcc.cuny.edu\\/urbanstudies\\/teaching_faculty\\/faculty_miller.htm\",\"12\":[\"131\"],\"8\":\"\"}}','2014-08-28 02:18:54','2014-08-28 02:18:54','1582f77b-8e35-4cb2-aa24-e9745745f7eb'),(84,134,3,1,'en_us',1,'','{\"typeId\":\"3\",\"authorId\":\"1\",\"title\":\"The Jim Crow North and the Global History of Segregated Cities\",\"slug\":\"the-jim-crow-north-and-the-global-history-of-segregated-cities\",\"postDate\":1409192480,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"2\":\"\",\"13\":[\"133\"],\"5\":{\"date\":\"4\\/3\\/2014\"},\"14\":[\"130\",\"132\"],\"17\":\"\"}}','2014-08-28 02:21:20','2014-08-28 02:21:20','7059afb4-691e-4fa2-971e-1d369df5f854'),(85,128,3,1,'en_us',3,'','{\"typeId\":\"3\",\"authorId\":\"1\",\"title\":\"Sisters in the Struggle: Sustaining Black Women\\u2019 Emancipation from Racism, Sexism and Violence\",\"slug\":\"sisters-in-the-struggle\",\"postDate\":1409191680,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"2\":\"\",\"13\":[\"127\",\"126\"],\"5\":{\"date\":\"3\\/6\\/2014\"},\"14\":[\"12\",\"121\",\"125\",\"123\"],\"17\":\"\"}}','2014-08-28 02:21:30','2014-08-28 02:21:30','f7a7f118-d294-4cbe-aaf3-9411d1391fe1'),(86,134,3,1,'en_us',2,'','{\"typeId\":\"3\",\"authorId\":\"1\",\"title\":\"The Jim Crow North and the Global History of Segregated Cities\",\"slug\":\"jim-crow-north-and-segregated-cities\",\"postDate\":1409192460,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"2\":\"\",\"13\":[\"133\"],\"5\":{\"date\":\"4\\/3\\/2014\"},\"14\":[\"130\",\"132\"],\"17\":\"\"}}','2014-08-28 02:21:46','2014-08-28 02:21:46','a5c652cc-54b2-4f01-a0ab-fdef09f4fbb5'),(87,136,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Peniel Joseph\",\"slug\":\"peniel-joseph\",\"postDate\":1409192650,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Tufts University\",\"10\":\"\",\"9\":\"Peniel.Joseph@tufts.edu\",\"11\":\"http:\\/\\/www.penielejoseph.com\\/\",\"12\":[\"135\"],\"8\":\"PenielJoseph\"}}','2014-08-28 02:24:10','2014-08-28 02:24:10','018eb02f-85f1-4e58-ac4c-8e86467cee2b'),(88,138,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Gloria Richardson\",\"slug\":\"gloria-richardson\",\"postDate\":1409192805,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"SNCC and former leader of the Cambridge movement\",\"10\":\"\",\"9\":\"\",\"11\":\"\",\"12\":[\"137\"],\"8\":\"\"}}','2014-08-28 02:26:45','2014-08-28 02:26:45','a0bfb158-dac1-4151-9d8d-170c87fff038'),(89,140,3,1,'en_us',1,'','{\"typeId\":\"3\",\"authorId\":\"1\",\"title\":\"The Biography of Global Black Power Politics: Stokely Carmichael and Walter Rodney\",\"slug\":\"global-black-power-politics\",\"postDate\":1409193106,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"2\":\"\",\"13\":[\"139\",\"20\"],\"5\":{\"date\":\"5\\/1\\/2014\"},\"14\":[\"37\",\"136\",\"138\"],\"17\":\"\"}}','2014-08-28 02:31:46','2014-08-28 02:31:46','a162b377-604c-4aee-8953-d0cd7e2dca66'),(90,142,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Hasan Kwame Jeffries\",\"slug\":\"hasan-kwame-jeffries\",\"postDate\":1409193443,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Ohio State University\",\"10\":\"<p>Dr. Jeffries is Associate Professor of History at Ohio State University. He specializes in 20th century African American history and has an expertise in the Civil Rights and Black Power Movements. He is the author of the newly released <em>Bloody Lowndes: Civil Rights and Black Power in Alabama\\u2019s Black Belt<\\/em> (New York University Press, 2009). <em>Bloody Lowndes<\\/em> tells the remarkable story of the local people and SNCC organizers who ushered in the Black Power era by transforming rural Lowndes County, Alabama.<\\/p>\",\"9\":\"Jeffries.57@osu.edu\",\"11\":\"http:\\/\\/history.osu.edu\\/directory\\/Jeffries57\",\"12\":[\"141\"],\"8\":\"\"}}','2014-08-28 02:37:23','2014-08-28 02:37:23','760b87e5-4dcc-4c4c-9a8b-949e8fbfd8d6'),(91,144,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Ujju Aggarwal\",\"slug\":\"ujju-aggarwal\",\"postDate\":1409193568,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Sarah Lawrence College\",\"10\":\"<p>Dr. Aggarwal received her PhD from the Graduate Center of the City University of New York, and currently teaches at&nbsp;Sarah Lawrence College. She is a cultural anthropologist whose work examines how post-Brown v. Board of Education \\u201cchoice\\u201d became central to how rights, freedom, and citizenship were imagined, structured, and constrained. Currently she works with the Parent Leadership Project at the Bloomingdale Family Head Start Center and is a member of the national collective of INCITE!<\\/p>\",\"9\":\"\",\"11\":\"\",\"12\":[\"143\"],\"8\":\"\"}}','2014-08-28 02:39:28','2014-08-28 02:39:28','1cf7164e-48fd-47e8-9e52-4edfc8a347d7'),(92,146,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Stefan Bradley\",\"slug\":\"stefan-bradley\",\"postDate\":1409193768,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"St. Louis University\",\"10\":\"<p>Dr. Bradley teaches at Saint Louis University including courses in African American Youth Movements in the 20th Century and Civil Rights in America, 1865-1965. His primary research area is recent U.S. history with an emphasis on the African American experience. He is fascinated with the efforts and abilities of black college students to change not only their scholastic environments but also the communities that surrounded their institutions of higher learning. He is the author of <em>Harlem vs. Columbia University: Black Student Power in the Late 1960s<\\/em> (Urbana: University of Illinois Press, 2009), Winner of the Phillis Wheatley Book Prize.<\\/p>\",\"9\":\"sbradle7@slu.edu\",\"11\":\"http:\\/\\/www.slu.edu\\/department-of-history\\/faculty-and-staff\\/regular-faculty\\/stefan-m-bradley\",\"12\":[\"145\"],\"8\":\"\"}}','2014-08-28 02:42:48','2014-08-28 02:42:48','b9d9ff0a-c123-46d9-a10d-b8d0c6cd3ddf'),(93,149,3,1,'en_us',1,'','{\"typeId\":\"3\",\"authorId\":\"1\",\"title\":\"Education for Liberation: How Parents, Teachers, and Students Organize for Self-Emancipation\",\"slug\":\"education-for-liberation\",\"postDate\":1409193960,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"2\":\"<p>\\\"The struggle for educational access and equality has been at the heart of the Black freedom movement. From pre-K to college access, black people have fought to open the structures of education, secure equitable resources, and make the curriculum and teaching staff reflect the diversity of America. Black mothers and Black students have led the way. Join Professors Hasan Jeffries, Stefan Bradley, and Ujju Aggarwal for a discussion of their new work on Education for Liberation.\\\"&nbsp;<\\/p><p><em>-- Jeanne Theoharris<\\/em><\\/p>\",\"13\":[\"148\",\"147\"],\"5\":{\"date\":\"6\\/6\\/2014\"},\"14\":[\"142\",\"144\",\"146\"],\"17\":\"\"}}','2014-08-28 02:46:00','2014-08-28 02:46:00','d65630b4-d62d-41d4-bac4-8919ad70683f'),(94,68,3,1,'en_us',4,'','{\"typeId\":\"3\",\"authorId\":\"1\",\"title\":\"The Urban Crisis: An Unfinished Agenda\",\"slug\":\"the-urban-crisis\",\"postDate\":1408935840,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"2\":\"<p>\\\"The time is ripe to revisit the unfinished agenda of the Black Revolt against the urban crisis: What is to be done? The Stop Killer Cops Campaign has a rich yet neglected history from the shooting of black children in Brooklyn in the 1970s to the shooting of Michael Brown in Ferguson in 2014.&nbsp;<\\/p><p>This roundtable of experts will unpack the congested issues of the urban crisis and suggest some current alternatives. Clarence Taylor is a pioneering expert on Civil Rights in the Jim Crow North, writing a book on the history of police brutality in NYC. Junius Williams is a veteran of the Student Nonviolent Coordinating Committee or SNCC and the Students for a Democratic Society or SDS, who pioneered advocacy planning and community development. Mr. Williams will discuss his memoir, Unfinished Agenda: Urban Politics in the Era of Black Power. And, Robert Curvin is a veteran of the Congress of Racial Equality or CORE in Essex County, New Jersey, former dean at the New School & past member of the New York Times editorial board, who has stayed on the cutting edge of alternative community development and economic empowerment from his work at the Ford Foundation to his teaching at Rutgers University. Mr. Curvin will discuss his new book, with an overview of those issues in Inside Newark: Decline, Rebellion, and the Search for Transformation.\\\"<\\/p><p><em>-- Komozi Woodard<\\/em><\\/p>\",\"13\":[\"66\",\"67\",\"19\"],\"5\":{\"date\":\"9\\/4\\/2014\"},\"14\":[\"69\",\"70\",\"32\"],\"17\":\"\"}}','2014-08-28 02:48:28','2014-08-28 02:48:28','002c1652-f561-410e-8aed-449d8c21ce70'),(95,70,4,1,'en_us',2,'','{\"typeId\":\"5\",\"authorId\":\"1\",\"title\":\"Junius Williams\",\"slug\":\"junius-williams\",\"postDate\":1408975320,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Rutgers University Newark\",\"10\":\"\",\"9\":\"\",\"11\":\"\",\"12\":[\"152\"],\"8\":\"\"}}','2014-08-28 02:51:02','2014-08-28 02:51:02','82977a14-d6a8-4a32-bc5d-410e2bb0fbc0'),(96,69,4,1,'en_us',2,'','{\"typeId\":\"5\",\"authorId\":\"1\",\"title\":\"Robert Curvin\",\"slug\":\"robert-curvin\",\"postDate\":1408975140,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Rutgers University, Bloustein School of Planning and Public Policy\",\"10\":\"\",\"9\":\"\",\"11\":\"\",\"12\":[\"153\"],\"8\":\"\"}}','2014-08-28 02:55:45','2014-08-28 02:55:45','f6fb4e23-da18-4a88-b69d-3125a61109a0'),(97,155,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Charles Payne\",\"slug\":\"charles-payne\",\"postDate\":1409194839,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"University of Chicago\",\"10\":\"\",\"9\":\"\",\"11\":\"http:\\/\\/ssascholars.uchicago.edu\\/c-payne\\/content\\/research-and-biography-27\",\"12\":[\"154\"],\"8\":\"\"}}','2014-08-28 03:00:39','2014-08-28 03:00:39','c8d1abc5-3e25-49af-bddf-156a78b8b6df'),(98,157,3,1,'en_us',1,'','{\"typeId\":\"3\",\"authorId\":\"1\",\"title\":\"Education for Liberation and Freedom Schooling\",\"slug\":\"education-for-liberation-and-freedom-schooling\",\"postDate\":1409195040,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"2\":\"\",\"13\":[\"156\",\"18\"],\"5\":{\"date\":\"9\\/2\\/2014\"},\"14\":[\"31\",\"155\"],\"17\":\"\"}}','2014-08-28 03:04:00','2014-08-28 03:04:00','045ce769-08a6-4894-9a27-cee4757433a4'),(99,159,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Barbara Winslow\",\"slug\":\"barbara-winslow\",\"postDate\":1409195160,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Brooklyn College\",\"10\":\"\",\"9\":\"\",\"11\":\"http:\\/\\/www.brooklyn.cuny.edu\\/web\\/academics\\/faculty\\/faculty_profile.jsp?faculty=264\",\"12\":[\"158\"],\"8\":\"\"}}','2014-08-28 03:06:00','2014-08-28 03:06:00','74797bce-3c4d-4659-8fc9-736556675503'),(100,161,4,1,'en_us',1,'','{\"typeId\":null,\"authorId\":\"1\",\"title\":\"Zinga Fraser\",\"slug\":\"zinga-fraser\",\"postDate\":1409195289,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Brooklyn College CUNY \",\"10\":\"\",\"9\":\"ZFraser@brooklyn.cuny.edu\",\"11\":\"http:\\/\\/www.zingafraser.com\\/\",\"12\":[\"160\"],\"8\":\"\"}}','2014-08-28 03:08:09','2014-08-28 03:08:09','30870ced-3dff-4316-ab0a-a911c0f8034d'),(101,163,3,1,'en_us',1,'','{\"typeId\":\"3\",\"authorId\":\"1\",\"title\":\"The Political Life and Legacy of Shirley Chisholm\",\"slug\":\"shirley-chisholm\",\"postDate\":1409195525,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"2\":\"\",\"13\":[\"162\"],\"5\":{\"date\":\"11\\/6\\/2014\"},\"14\":[\"161\",\"159\",\"88\"],\"17\":\"\"}}','2014-08-28 03:12:05','2014-08-28 03:12:05','fb4df172-d913-4b01-b23c-335576ba6978'),(102,163,3,1,'en_us',2,'','{\"typeId\":\"3\",\"authorId\":\"1\",\"title\":\"The Political Life and Legacy of Shirley Chisholm\",\"slug\":\"shirley-chisholm\",\"postDate\":1409195520,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"2\":\"\",\"13\":[\"162\"],\"5\":{\"date\":\"11\\/6\\/2014\"},\