,1,'','{\"typeId\":\"3\",\"authorId\":\"1\",\"title\":\"Harlem\'s Fallen Warriors: Maya Angelou, General Baker, Mae Mallory, Elombe Brath, and Amiri Baraka\",\"slug\":\"harlems-fallen-warriors-maya-angelou-general-baker-mae-mallory-elombe-brath-and-amiri-baraka\",\"postDate\":1429200180,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"13\":[\"282\",\"283\"],\"5\":{\"date\":\"6\\/4\\/2015\"},\"18\":\"\",\"19\":\"\",\"24\":\"\",\"14\":[\"12\",\"45\",\"278\"],\"17\":\"\"}}','2015-04-16 16:05:36','2015-04-16 16:05:36','f9a3a1f7-71de-4968-b4c2-3e1e5dd67398'),(392,275,4,1,'en_us',2,'','{\"typeId\":\"5\",\"authorId\":\"1\",\"title\":\"Sonia Lee\",\"slug\":\"sonia-lee\",\"postDate\":1429199760,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Department of History, Washington University in St. Louis\",\"10\":\"\",\"9\":\"solee@wustl.edu\",\"11\":\"https:\\/\\/history.artsci.wustl.edu\\/lee\",\"12\":[\"285\"],\"8\":\"\"}}','2015-04-16 16:07:54','2015-04-16 16:07:54','5b99b457-fcb5-40d7-8618-306600005afa'),(393,276,4,1,'en_us',2,'','{\"typeId\":\"5\",\"authorId\":\"1\",\"title\":\"Alejandra Marchevsky\",\"slug\":\"alejandra-marchevsky\",\"postDate\":1429199760,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Department of Liberal Studies, Cal State L.A.\",\"10\":\"\",\"9\":\"amarche@calstatela.edu\",\"11\":\"http:\\/\\/www.calstatela.edu\\/dept\\/libstudies\\/marchevsky.php\",\"12\":[\"286\"],\"8\":\"\"}}','2015-04-16 16:09:28','2015-04-16 16:09:28','f90c2b7b-7577-41db-9dea-b4b1b4b1c9f2'),(394,277,4,1,'en_us',2,'','{\"typeId\":\"5\",\"authorId\":\"1\",\"title\":\"Johanna Fernandez\",\"slug\":\"johanna-fernandez\",\"postDate\":1429199760,\"expiryDate\":null,\"enabled\":1,\"fields\":{\"7\":\"Department of History, CUNY Baruch\",\"10\":\"\",\"9\":\"Johanna.Fernandez@baruch.cuny.edu\",\"11\":\"\",\"12\":[\"287\"],\"8\":\"johannafernand\"}}','2015-04-16 16:10:58','2015-04-16 16:10:58','b3fda957-bcbe-4bd4-a5ce-494417b53ba6'),(395,278,4,1,'en_us',2,'','{\"typeId\":\"5\",\"au